	[ 'eans' => [ '4002458534485' ], 'html' => '<p>Kuglekanden i Ash Rose er tegnet af Ole Palsby i 1985 og rummer 0,94 liter. Kuglens form har det største rumfang med den mindste overflade, og kanden har dobbeltvægget AlfiDur-indsats.</p>' ],
	[ 'eans' => [ '5708642064514' ], 'html' => '<p>Nemo fra OBH er en ledningsfri elkedel på 1,0 liter med 2200 watt, skjult varmelegeme, hængslet og låsbart låg og vandstandsmål.</p>' ],
	[ 'eans' => [ '0763332083966' ], 'html' => '<p>Rise Tumbler i wax yellow på 473 ml fra Klean Kanteen. Krusets ergonomiske kurver ligger godt i hånden, og det er af rustfrit stål.</p>' ],
	[ 'eans' => [ '7340043325924' ], 'html' => '<p>Mrs. Potato er motivet på dette Elsa Beskow-krus med hank på 28 cl fra Design House Stockholm.</p>' ],
	[ 'eans' => [ '7340043325955' ], 'html' => '<p>Elsa Beskow-krus på 28 cl med hank og motivet Carrot fra Design House Stockholm.</p>' ],
	[ 'eans' => [ '7340043325948' ], 'html' => '<p>Mrs Broad Bean i grønne toner er motivet på dette Elsa Beskow-krus med hank, 28 cl, fra Design House Stockholm.</p>' ],
	[ 'eans' => [ '7340043325931' ], 'html' => '<p>Mrs Beetroot med varme røde toner pryder dette Elsa Beskow-krus på 28 cl fra Design House Stockholm.</p>' ],
	[ 'eans' => [ '5706631221337' ], 'html' => '<p>City To Go Cup i sort er et termokrus på 0,35 liter. Klikfunktionen i låget betjenes med én hånd.</p>' ],
	[ 'eans' => [ '5706631222457' ], 'html' => '<p>City To Go Cup i stål og sort fra Eva Solo rummer 0,35 liter og kan åbnes og lukkes med én hånd.</p>' ],
	[ 'eans' => [ '7320061140334' ], 'html' => '<p>Ostindia-kruset på 30 cl fra Rörstrand er af porcelæn. Emmy Almström tegnede serien i 1930 efter et porcelænsskår fra skibet Götheborg.</p>' ],
	[ 'eans' => [ '1200185025181' ], 'html' => '<p>Everyday Camp Mug i mat sort fra Stanley rummer 0,35 liter og er lavet til daglig brug.</p>' ],
	[ 'eans' => [ '14891635805916' ], 'html' => '<p>Seks mintgrønne underkopper på 15 cm til café latte fra Loveramics\' Tulip-serie, opkaldt efter koppernes tulipanform.</p>' ],
	[ 'eans' => [ '0727015846125' ], 'html' => '<p>Kenya-stempelkanden fra Bodum til 3 kopper rummer 0,35 liter. Kaffen er klar efter 3-4 minutter.</p>' ],
	[ 'eans' => [ '5709846034150' ], 'html' => '<p>Tabi i dusty green er en termoflaske på 0,55 liter fra Stelton, tegnet af den japanske designer Kazushige Miyake med organisk form og ergonomisk håndtag.</p>' ],
	[ 'eans' => [ '5709846034143' ], 'html' => '<p>Tabi i stål er Steltons termoflaske på 0,55 liter, tegnet af Kazushige Miyake med organisk form.</p>' ],
	[ 'eans' => [ '5713275256663' ], 'html' => '<p>Sky-termokruset i blå fra Georg Jensen er af blåt rustfrit stål og tegnet af Aurélien Barbry. Formen er asymmetrisk.</p>' ],
	[ 'eans' => [ '5709846021358' ], 'html' => '<p>To Theo-krus fra Stelton i mørk stentøj med råt look. Serien er inspireret af nordiske og japanske designtendenser.</p>' ],
	[ 'eans' => [ '5708642064132' ], 'html' => '<p>Daybreak Black fra OBH er en elkedel på 1,7 liter og 2200 watt med autosluk, tørkogningssikring og skjult element i bunden af rustfrit stål.</p>' ],
	[ 'eans' => [ '5712195093273' ], 'html' => '<p>Toppu-koppen fra OYOY har håndmalede striber i karamel og rosé, så hvert eksemplar er unikt.</p>' ],
	[ 'eans' => [ '5709846025516' ], 'html' => '<p>Fire Mix\'N\'Match-krus fra Rig-Tig i pastelfarverne lyserød, grøn, gul og blå. De er af glaseret stentøj og inspireret af loppefund.</p>' ],
	[ 'eans' => [ '0763332083942' ], 'html' => '<p>Rise Tumbler i iceberg rummer 473 ml. Termokruset har ergonomiske kurver og er fra Klean Kanteen.</p>' ],
	[ 'eans' => [ '0763332083959' ], 'html' => '<p>Rise Tumbler i brittany blue rummer 473 ml og har Climate Lock-isolering, så drikken holder sin temperatur længe.</p>' ],
	[ 'eans' => [ '0763332083928' ], 'html' => '<p>Sort Rise Tumbler fra Klean Kanteen på 473 ml. Termokruset har et stænksikkert skydelåg.</p>' ],
	[ 'eans' => [ '0763332083935' ], 'html' => '<p>Rise Tumbler i barely blue rummer 473 ml og har Climate Lock-isolering, som bevarer temperaturen.</p>' ],
	[ 'eans' => [ '14891635805855' ], 'html' => '<p>Seks røde underkopper på 15 cm til café latte fra Loveramics\' Tulip-kollektion.</p>' ],
	[ 'eans' => [ '0763332074254' ], 'html' => '<p>Rise Wine Tumbler i stellar rummer 296 ml og er til vin, kaffe eller cocktails. Fra Klean Kanteen.</p>' ],
	[ 'eans' => [ '4168430003766' ], 'html' => '<p>Ponza fra Tefal i hvid er en pumpekande på 1,9 liter, som holder væsken varm i op til 12 timer eller kold i op til 24 timer.</p>' ],
	[ 'eans' => [ '4168430003773' ], 'html' => '<p>Ponza i rød fra Tefal er en pumpekande på 1,9 liter. Den holder varmt i op til 12 timer og koldt i op til 24 timer.</p>' ],
	[ 'eans' => [ '7044876099495' ], 'html' => '<p>Elkedel i stål fra Wilfa på 1,0 liter og 1500 watt med ledningsopbevaring, automatisk sluk og vandstandsindikator. Den er lavet til mængder mellem 400 ml og 1 liter.</p>' ],
	[ 'eans' => [ '1210001900585' ], 'html' => '<p>Stay Hot fra Stanley i rose er et stabelbart termokop på 0,29 liter. Farven er rose quartz.</p>' ],
	[ 'eans' => [ '1210001900592' ], 'html' => '<p>Stay Hot i frost er et stabelbart termokrus på 0,29 liter af 18/8 rustfrit stål med pulverlakeret yderside.</p>' ],
	[ 'eans' => [ '1210001900578' ], 'html' => '<p>Stay Hot i cream er en stabelbar termokop på 0,29 liter fra Stanley.</p>' ],
	[ 'eans' => [ '1210001900561' ], 'html' => '<p>Sort Stay Hot fra Stanley er en stabelbar termokop på 0,29 liter.</p>' ],
	[ 'eans' => [ '1210001900608' ], 'html' => '<p>Stay Hot i ash er en stabelbar termokop på 0,29 liter fra Stanley til daglig brug.</p>' ],
	[ 'eans' => [ '1210001965096' ], 'html' => '<p>Café-To-Go i ash er et kompakt termokrus på 0,23 liter fra Stanley, tænkt som alternativ til engangskrus.</p>' ],
	[ 'eans' => [ '7330033000450' ], 'html' => '<p>Koppen fra Primus er et termokrus på 0,3 liter af rustfrit stål med dobbelte vægge til varme og kolde drikke.</p>' ],
	[ 'eans' => [ '7630135605929' ], 'html' => '<p>Shield ONE fra Sigg med Mickey &amp; Friends-motiv er en drikkeflaske i rustfrit stål på 0,5 liter til skoletasken, fritid og udflugter.</p>' ],
	[ 'eans' => [ '0727015831640' ], 'html' => '<p>To espressoglas fra Bodums Bistro-serie, hver med en hank. Glassene har dobbelt væg, så espressoen holder sig varm, og fingrene undgår at blive brændt på ydersiden.</p><p>Sættet rummer 2 stk. og tåler maskinopvask.</p>' ],
	[ 'eans' => [ '0763332074230' ], 'html' => '<p>Rise Wine Tumbler fra Klean Kanteen er en 296 ml drikkebæger i farven sea spray. Formen har ergonomiske konturer, og farven er hentet fra naturen.</p><p>Bægeret er tænkt til vin, men kan lige så godt bruges til kaffe eller en cocktail.</p>' ],
	[ 'eans' => [ '0763332074216' ], 'html' => '<p>Her er Klean Kanteens Rise Wine Tumbler i den lyse nuance tofu. Den rummer 296 ml og har ergonomiske konturer, der gør den behagelig at holde om.</p><p>Bægeret kan bruges til vin, kaffe eller cocktails, og farven er inspireret af naturen.</p>' ],
	[ 'eans' => [ '0763332074193' ], 'html' => '<p>Klean Kanteen Rise Wine Tumbler i den mørke farve Asphalt. Kapaciteten er 296 ml, og bægerets ergonomiske kontur giver et godt greb.</p><p>Det er designet til et glas vin, men fungerer også til kaffe eller en drink.</p>' ],
	[ 'eans' => [ '0763332074001' ], 'html' => '<p>Kid Cup fra Klean Kanteen er en drikkekop til børn på 296 ml i farven rouge red. Den er let at holde for små hænder og passer i de fleste kopholdere i barnevogne og autostole.</p><p>Koppen leveres med stænksikkert låg og et genanvendeligt sugerør i samme farve.</p>' ],
	[ 'eans' => [ '0763332073998' ], 'html' => '<p>Drikkekoppen Kid Cup i sparkling grape rummer 296 ml. Den er formet, så små hænder kan holde om den, og den passer i kopholdere på de fleste barnevogne og autostole.</p><p>Låget er stænksikkert, og et genanvendeligt sugerør i matchende farve følger med.</p>' ],
	[ 'eans' => [ '0763332073981' ], 'html' => '<p>Klean Kanteens Kid Cup i farven crocus petal er en børnekop på 296 ml. Den er nem for små hænder at holde, og den glider ned i kopholdere i barnevogne og autostole.</p><p>I pakken er der et stænksikkert låg og et genanvendeligt sugerør, der matcher koppens farve.</p>' ],
	[ 'eans' => [ '0763332073974' ], 'html' => '<p>Her får du Kid Cup i hawaiian ocean fra Klean Kanteen. Koppen på 296 ml er lavet til børn og er let at gribe om.</p><p>Den passer i de fleste kopholdere på barnevogne og autostole. Låget er stænksikkert, og sugerøret i samme farve kan bruges igen og igen.</p>' ],
	[ 'eans' => [ '4977642033436' ], 'html' => '<p>Hario-flasken til cold brew har et indbygget filter, så du kan lave koldbryg og opbevare den i samme beholder. Tanken er, at kaffen trækker i køleskabet og står klar til at hælde op.</p><p>Flasken er i nuancen Mocca.</p>' ],
	[ 'eans' => [ '5056288464411' ], 'html' => '<p>Et tiki-krus i bambus på 320 ml med et råt, udskåret udtryk i stil med de klassiske polynesiske krus. Naturfarven giver en tropisk fremtoning på bordet.</p><p>Kruset er lavet til at servere drinks i og passer til en hjemmebar med tiki-tema.</p>' ],
	[ 'eans' => [ '8720389037276' ], 'html' => '<p>HD9411/70 er en elkedel fra Philips\' 3000-serie i en dyb blå farve. Den bruges til at koge vand til te og kaffe eller til hurtige, varme retter.</p><p>Designet er moderne og holdt enkelt, så kedlen passer ind i de fleste køkkener.</p>' ],
	[ 'eans' => [ '8006363041591' ], 'html' => '<p>Bialettis induktionsplade er en adapter, der gør det muligt at bruge mokkabrygger i aluminium på en induktionskogeplade. Pladen opvarmer bryggeren, selv om den ikke selv er induktionsegnet.</p><p>Den kan også bruges til andet køkkengrej, som ikke virker på induktion.</p>' ],
	[ 'eans' => [ '0763332065122' ], 'html' => '<p>TKWide fra Klean Kanteen er en termokande på 946 ml i farven marigold med drikketud. Den er stødsikker og har dobbelt isolerede vægge, så drikken kan holde sig kold på en lang udflugt.</p><p>Kanden er lavet til at drikke direkte fra.</p>' ],
	[ 'eans' => [ '8720604946314' ], 'html' => '<p>To store porcelænskrus fra Pip Studio i Flower Festival-kollektionen, her i rosa. Hvert krus rummer 35 cl, så der er plads til en rigelig portion kaffe eller te.</p><p>Sættet passer til morgenbordet og kan kombineres med resten af serien.</p>' ],
	[ 'eans' => [ '8720512745054' ], 'html' => '<p>Sæt med to krus i Pip Studios serie Flower Festival. Baggrunden er blå, og mønstret består af fantasifulde chintzblomster i rød og pink, suppleret af lyseblå og grønne nuancer.</p><p>Hvert krus har plads til 35 cl.</p>' ],
	[ 'eans' => [ '7333282008802' ], 'html' => '<p>Elkedel fra Emerio med plads til 1,7 liter og en effekt på 2200 watt, så vandet hurtigt bliver varmt. Den bruges til te, kaffe og til madlavning, hvor der skal bruges kogende vand.</p>' ],
	[ 'eans' => [ '7350034659426' ], 'html' => '<p>Emerios elkedel på 1,5 liter er trådløs og har tænd/sluk-knap ved håndtaget. Når kedlen er i gang, lyser det indeni.</p><p>Fokus er på et pænt udseende, så den kan stå fremme på køkkenbordet.</p>' ],
	[ 'eans' => [ '7340043324521' ], 'html' => '<p>Kruset fra Design House Stockholm bærer et detaljeret rosemotiv inspireret af Elsa Beskows illustrationer. Udtrykket er legende, men afbalanceret.</p><p>Det rummer 28 cl og hører til serien Elsa Beskow, her i varianten rose.</p>' ],
	[ 'eans' => [ '7340043315819' ], 'html' => '<p>Valmuen er hovedmotivet på dette 28 cl krus fra Design House Stockholm. Dekorationen er hentet fra Elsa Beskows illustrationer, hvor natur og menneskelige træk smelter sammen.</p><p>Resultatet er levende, men roligt.</p>' ],
	[ 'eans' => [ '7340043322817' ], 'html' => '<p>Nasturtium, på dansk tallerkensmækker, er motivet på dette krus på 28 cl. Mønstret kommer fra Elsa Beskow-serien hos Design House Stockholm, hvor planteformerne får et legende, næsten menneskeligt udtryk.</p><p>Kruset giver bordet en varm og levende farve.</p>' ],
	[ 'eans' => [ '7340043319145' ], 'html' => '<p>Mrs. Aster-motivet i Design House Stockholms Elsa Beskow-serie er gengivet med fine linjer og bløde nuancer på et krus på 28 cl.</p><p>Illustrationen trækker på Beskows univers, hvor natur og menneskelige træk går i ét, og giver kruset et roligt og gennemarbejdet udtryk.</p>' ],
	[ 'eans' => [ '7340043315840' ], 'html' => '<p>Marguerite-kruset i Elsa Beskow-serien fra Design House Stockholm har et rytmisk blomstermotiv, der giver en let fornemmelse af bevægelse.</p><p>Det rummer 28 cl, og stilen er lys og venlig.</p>' ],
	[ 'eans' => [ '7340043325153' ], 'html' => '<p>Krus på 28 cl med syrenmotiv fra Design House Stockholm. Motivet er symmetrisk opbygget og bygger på Elsa Beskows illustrationer.</p><p>De detaljerede figurer og afdæmpede farver giver et roligt, velafbalanceret udtryk, som passer til serien Elsa Beskow.</p>' ],
	[ 'eans' => [ '7340043318858' ], 'html' => '<p>Children of the Forest bringer skovens figurer ind på et 28 cl krus fra Design House Stockholm. Motivet er finurligt og detaljerigt og bygger på Elsa Beskows fortællinger.</p><p>Dekorationen har et blødt, fortællende præg.</p>' ],
	[ 'eans' => [ '7340043318841' ], 'html' => '<p>Aunt Lavender-motivet pryder dette 28 cl krus fra Design House Stockholm. Lavendelfarvede toner og bløde linjer giver en rolig, harmonisk helhed, som stammer fra Elsa Beskows illustrationer.</p><p>Formen er enkel, så dekorationen får lov at stå i centrum.</p>' ],
	[ 'eans' => [ '7340043318827' ], 'html' => '<p>Aunt Green er et grønt motiv fra Elsa Beskow-serien hos Design House Stockholm. Kruset på 28 cl har et frisk og naturligt look, hvor bevægelsen i figurerne skaber en lille fortælling.</p>' ],
	[ 'eans' => [ '7340043318834' ], 'html' => '<p>Krus i serien Elsa Beskow fra Design House Stockholm med motivet Aunt Brown. De varme brune nuancer og bløde linjer giver et jordnært udtryk.</p><p>Kruset rummer 28 cl, og små fortællinger i illustrationen giver liv til designet.</p>' ],
	[ 'eans' => [ '7340043323692' ], 'html' => '<p>August-motivet på dette 28 cl krus fra Design House Stockholm samler mennesker og natur i en detaljeret fortælling. Farverne er varme, og de mange små figurer giver et levende udtryk.</p><p>Motivet bygger på Elsa Beskows illustrationer og leder tankerne hen på sensommer og samvær.</p>' ],
	[ 'eans' => [ '7320062104854' ], 'html' => '<p>Swedish Grace Gala-koppen fra Rörstrand rummer 30 cl og er lavet af hvidt feldspatporcelæn. Dekorationen er et klassisk mønster, der giver kaffepausen et mere elegant præg.</p>' ],
	[ 'eans' => [ '7340043313907' ], 'html' => '<p>Krus fra serien Elsa Beskow, som er tegnet af Catharina Kippel med udgangspunkt i børnebogsforfatterens fortællinger. Motivet her er eventyrfiguren Fru Dild.</p><p>Det er produceret af Design House Stockholm.</p>' ],
	[ 'eans' => [ '7340043311644' ], 'html' => '<p>Elsa Beskow-krus fra Design House Stockholm med eventyrfiguren Jomfru Kornblomst som motiv. Serien er designet af Catharina Kippel, som har tolket Beskows kendte fortællinger.</p>' ],
	[ 'eans' => [ '7340043307340' ], 'html' => '<p>Dette krus med hank er en del af Elsa Beskow-serien fra Design House Stockholm. Motivet er eventyrfiguren Maskros, og serien er designet af Catharina Kippel ud fra Beskows historier.</p>' ],
	[ 'eans' => [ '7340043306022' ], 'html' => '<p>Krus uden hank i Elsa Beskow-serien, designet af Catharina Kippel for Design House Stockholm. Dekorationen viser figurerne fra Jordbærfamilien.</p><p>Serien bygger på børnebogsforfatteren Elsa Beskows fortællinger.</p>' ],
	[ 'eans' => [ '7340043305988' ], 'html' => '<p>Krus med hank fra Design House Stockholm i serien Elsa Beskow. Motivet er Videung, figuren fra sangen Sov, min lille Videung.</p><p>Serien er designet af Catharina Kippel.</p>' ],
	[ 'eans' => [ '5709846031555' ], 'html' => '<p>To krus fra Stelton på 0,2 liter, lavet til at passe sammen med termokanderne i den klassiske EM77-serie. De fås i tre farver, som hver matcher sin termokande. Dette sæt er i lavendel.</p>' ],
	[ 'eans' => [ '4977642031623' ], 'html' => '<p>Hario V60 Suiren er en pour-over-dripper i sort og hvid med modulært design. Den har en stabil basering, hvor 12 aftagelige ribber klikkes på plads.</p><p>Opbygningen følger den klassiske V60-tilgang til filterkaffe.</p>' ],
	[ 'eans' => [ '5706631226950' ], 'html' => '<p>Urban fra Eva Solo er en termoflaske på 0,5 liter i farven emerald green. Den er lavet af rustfrit stål med dobbelte vægge og vakuumeffekt, så vandet bliver koldt længe.</p>' ],
	[ 'eans' => [ '5010576673961' ], 'html' => '<p>Thermos Travel Pro er et termokrus på 0,4 liter i matsort rustfrit stål. Tryklåget slutter tæt, så indholdet ikke løber ud.</p><ul><li>Skal vaskes op i hånden</li><li>10 års garanti på varme- og kølefunktionen</li><li>Brugsanvisning og plejevejledning følger med</li></ul>' ],
	[ 'eans' => [ '4002458463297' ], 'html' => '<p>Alfi Eco er en termokande på 1 liter i plast, designet af Martin Hauenstein. Den kan bruges med én hånd og er nem at gøre ren.</p><ul><li>Højde: 26 cm</li><li>Diameter i bunden: 14,5 cm</li></ul>' ],
	[ 'eans' => [ '1210001906976' ], 'html' => '<p>Stanley Adventure Pint er et termokrus på 0,47 liter i farven frost. Konstruktionen er robust og lavet i 18/8 rustfrit stål.</p><p>Det kan afløse engangskrus og skrøbelige glas, når du skal have drikken med.</p>' ],
	[ 'eans' => [ '7630135603611' ], 'html' => '<p>SIGG WMB ONE i udgaven Stand Together er en drikkeflaske på 0,6 liter af 100 % genanvendt aluminium, fremstillet i Schweiz. Designet er inspireret af Harry Potter-serien.</p><p>Flasken er let og holdbar og kan komme med i skoletasken eller til fritidsaktiviteter.</p>' ],
	[ 'eans' => [ '7630135603666' ], 'html' => '<p>Hermione pryder denne SIGG WMB ONE, en let drikkeflaske på 0,6 liter i genanvendt aluminium. Flasken er fremstillet i Schweiz.</p><p>Den er lavet til skoledage, træning og fritid.</p>' ],
	[ 'eans' => [ '7630135603529' ], 'html' => '<p>Batman Action Blue er et farverigt motiv på SIGG WMB ONE. Vandflasken rummer 0,6 liter og er lavet i Schweiz af 100 % genanvendt aluminium.</p><p>Den er let, holdbar og passer i skoletasken.</p>' ],
	[ 'eans' => [ '7630135606018' ], 'html' => '<p>SIGG WMB ONE med Disney-motivet Simba og Nala er en let aluminiumsflaske på 0,6 liter, fremstillet i Schweiz. Den er lavet til daglig brug i skole og træning og på weekendens ture.</p>' ],
	[ 'eans' => [ '7630135606025' ], 'html' => '<p>Retro-mønstret med Mickey kendetegner denne SIGG WMB ONE. Flasken er fremstillet i Schweiz af 100 % genanvendt aluminium og rummer 0,6 liter.</p><p>Den er let og slidstærk og tænkt til hverdagen, fra skoledagen til weekendens aktiviteter.</p>' ],
	[ 'eans' => [ '0719812051925' ], 'html' => '<p>OXO Brew Steel POP er en kaffebeholder på 1,6 liter i rustfrit stål med ske. Åbne kaffeposer lukker luft og fugt ind, som forringer smag og aroma, og beholderen er lavet til at undgå det.</p><p>POP-låget gør det nemt at åbne og lukke.</p>' ],
	[ 'eans' => [ '6411255126447' ], 'html' => '<p>Marimekkos Unikko-kopper uden hank kommer i sæt med to på 2 dl. Maija Isolas klassiske valmuemønster mødes her med Sami Ruotsalainens Oiva-design.</p><p>Farverne er hvid, beige, lys sand og mørkegrøn. Kopperne kan bruges til kaffe eller espresso.</p>' ],
	[ 'eans' => [ '0763332083713' ], 'html' => '<p>Rise Vacuum Classic er en termoflaske på 355 ml i farven Iceberg, leveret med Arch Loop-låg. Vakuumisoleringen holder både varme og kulde, og yderfladen er tør uden kondens, så tasken ikke bliver fugtig.</p>' ],
	[ 'eans' => [ '0763332083720' ], 'html' => '<p>Termoflasken Rise Vacuum Classic rummer 355 ml og kommer med Arch Loop-låg i nuancen Dusty Orchid. Vakuumisolering bevarer temperaturen på drikken, og overfladen danner ikke kondens.</p>' ],
	[ 'eans' => [ '0763332083706' ], 'html' => '<p>Klean Kanteens Rise Vacuum Classic på 355 ml i farven Brittany Blue har Arch Loop-låg. Vakuumisoleringen holder drikken varm eller kold længe, og flasken bliver ikke våd udenpå.</p>' ],
	[ 'eans' => [ '1210001900516' ], 'html' => '<p>Stanley Transit Fliptop er et termokrus på 0,35 liter i den bløde nuance peach rose. Den kompakte størrelse gør det nemt at have med i tasken eller rygsækken.</p><p>Kruset er tænkt til pendling, arbejde og rolige kaffepauser.</p>' ],
	[ 'eans' => [ '1200185029776' ], 'html' => '<p>Her er Stanley Transit Fliptop i farven hammertone green, som bygger på mærkets klassiske designtradition. Termokruset rummer 0,35 liter og er kompakt nok til at følge med hele dagen.</p>' ],
	[ 'eans' => [ '1210001900523' ], 'html' => '<p>Stanley Transit Fliptop i blue sky bruger AeroLight-teknologi, som gør kruset op til 33 % lettere end traditionelle modeller i rustfrit stål. Kapaciteten er 0,35 liter.</p><p>Formen passer til de fleste kopholdere i bilen.</p>' ],
	[ 'eans' => [ '7394150186992' ], 'html' => '<p>Ted er et gult termokrus fra Sagaform. Det kan bruges til morgenkaffen, te i løbet af dagen, varm kakao eller kolde drikke.</p><p>Farven er frisk, og funktionen er gennemtænkt til en aktiv hverdag.</p>' ],
	[ 'eans' => [ '0763332082785' ], 'html' => '<p>Rise Classic-termoflasken fra Klean Kanteen på 355 ml i farven Cabbage har Arch Loop-låg. Den slanke form gør den lille og handy.</p><p>Flasken er til hverdagen og til dagene med aktiviteter ude.</p>' ],
	[ 'eans' => [ '0763332082778' ], 'html' => '<p>Pink Lemonade er et legende, tofarvet rosa design på Klean Kanteens Rise Classic-termoflaske. Den rummer 355 ml og har Arch Loop-låg.</p><p>Flasken er lavet til hverdagen og til dig, der er meget på farten.</p>' ],
	[ 'eans' => [ '0763332082761' ], 'html' => '<p>Klean Kanteens Rise Classic i farven Acacia, en varm, naturlig gul. Termoflasken rummer 355 ml og er udstyret med Arch Loop-låg.</p>' ],
	[ 'eans' => [ '0763332082754' ], 'html' => '<p>Rise Classic-termoflasken i Barely Blue er en afdæmpet blågrå flaske på 355 ml fra Klean Kanteen. Arch Loop-låget følger med.</p><p>Udtrykket er diskret og stilrent, og flaskens design tager hensyn til både udseende og funktion.</p>' ],
	[ 'eans' => [ '0763332082747' ], 'html' => '<p>Sort Rise Classic-termoflaske fra Klean Kanteen på 355 ml med Arch Loop-låg. Designet er minimalistisk, og størrelsen er kompakt.</p><p>Flasken er tænkt til at kunne bruges i både mødelokalet og i naturen.</p>' ],
	[ 'eans' => [ '1210001965188' ], 'html' => '<p>Stanley Café-To-Go er et termokrus på 0,35 liter til den daglige kaffepause. Det er tænkt som en holdbar erstatning for engangskrus.</p><p>Krusene fra Stanley er kendt for holdbarhed, og her er den kombineret med et moderne design.</p>' ],
	[ 'eans' => [ '7630135603628' ], 'html' => '<p>Harry Potter-motiver pryder denne SIGG WMB ONE, en let og slidstærk drikkeflaske på 0,6 liter. Den er fremstillet i Schweiz af 100 % genanvendt aluminium.</p><p>Flasken kan komme med i skoletasken eller til fritidsaktiviteter.</p>' ],
	[ 'eans' => [ '7394150003527' ], 'html' => '<p>Kop med underkop i Byons Fruity-serie, hvor formen er hentet fra en saftig fersken. Den legende, udtryksfulde form og de varme farver giver kaffepausen lidt personlighed.</p><p>Farven er fersken.</p>' ],
	[ 'eans' => [ '5057982082369' ], 'html' => '<p>Pisa er en stempelkande til 3 kopper fra La Cafetière i sort. Designet er inspireret af italiensk tradition og kombinerer moderne linjer med klassiske detaljer.</p><p>Kanden bruges til klassisk stempelbrygget kaffe.</p>' ],
	[ 'eans' => [ '4003686441439' ], 'html' => '<p>Snemand i relief pryder dette krus fra Villeroy & Bochs kollektion Toy\'s Fantasy. Motivet giver vinterstemning på bordet, og kruset er beregnet til varme drikke som kaffe.</p>' ],
	[ 'eans' => [ '8010072250434' ], 'html' => '<p>Mælkekande i rustfrit stål fra La Pavoni med plads til 35 cl. Den bruges til at servere mælk eller til at skumme den til espresso- og kaffedrikke.</p>' ],
	[ 'eans' => [ '0763332074537' ], 'html' => '<p>Rise Tumbler fra Klean Kanteen i farven stellar, med en kapacitet på 473 ml. Den er lavet af 90 % genanvendt 18/8 rustfrit stål og har ergonomisk form.</p><p>Vakuumisoleringen Climate Lock er prisbelønnet og holder temperaturen på drikken.</p>' ],
	[ 'eans' => [ '4977642221833' ], 'html' => '<p>Hario-termokop med keramisk belægning indvendigt og dobbelt væg. Belægningen er valgt for at bevare smagen af kaffe og te, og isoleringen hjælper med at holde temperaturen.</p><p>Koppen er lavet til kaffeentusiaster.</p>' ],
	[ 'eans' => [ '4001627010959' ], 'html' => '<p>Kapselindsats fra Graef i blå, som gør det muligt at bruge Nescafé Dolce Gusto-kapsler i en kaffemaskine. Indsatsen udvider maskinens muligheder og gør det nemt at brygge med disse kapsler.</p>' ],
	[ 'eans' => [ '8718215106081' ], 'html' => '<p>Tiki-krus i brun keramik på 330 ml med et udtryksfuldt ansigt inspireret af maorikulturen. Overfladen har detaljeret struktur og en antik æstetik.</p><p>Fra Barprofessional og lavet til at servere cocktails i.</p>' ],
	[ 'eans' => [ '8718215106043' ], 'html' => '<p>Easter Islander er et tiki-krus på 450 ml fra Barprofessional, formet efter de monumentale Moai-skulpturer på Påskeøen. Det giver cocktails en eksotisk præsentation.</p>' ],
	[ 'eans' => [ '0763332064828' ], 'html' => '<p>TKWide er en vakuumisoleret flaske på 355 ml i sort med Twist Cap, fra Klean Kanteen. Den kan bruges som vandflaske, iskaffekrus, sportsflaske eller isoleret kop.</p><p>Designet lægger vægt på alsidighed og bærbarhed.</p>' ],
	[ 'eans' => [ '0727015846163' ], 'html' => '<p>Bodum Kenya er en stempelkande til 4 kopper med 0,5 liter. Kaffen laves ved at komme nymalede bønner i kanden, hælde varmt vand over og trykke filteret ned efter 3-4 minutter.</p>' ],
	[ 'eans' => [ '0763332055055' ], 'html' => '<p>Termokop med sugerørslåg fra Klean Kanteen på 473 ml i grøn. Dobbelt isolerede vægge kan holde varme drikke varme i op til fire timer.</p><p>Koppen kan bruges til kaffe, smoothies, øl, vand eller suppe.</p>' ],
	[ 'eans' => [ '6411801026375' ], 'html' => '<p>Termoflaske på 0,45 liter fra Arabia med Lille My fra Moomin-universet.</p><p>Flasken holder drikke varme eller kolde.</p>' ],
	[ 'eans' => [ '7340154206341' ], 'html' => '<p>To kopper på 28 cl fra Potteryjo i farven cotton white. De hører til serien Daria, som Johanna Hampf skabte i 2017, og har et tidløst og elegant design.</p>' ],
	[ 'eans' => [ '4977642037441' ], 'html' => '<p>Hario-flaske til cold brew i sort med indbygget filter. Du kan lave koldbryg og have den i køleskabet, klar til at skænke op.</p><p>Flaskens elegante udtryk gør, at den kan stå fremme.</p>' ],
	[ 'eans' => [ '0763332055079' ], 'html' => '<p>Klean Kanteens termokop på 473 ml i farven berry bright, med sugerørslåg. Dobbelt isolerede vægge kan holde varme drikke varme i op til fire timer.</p><p>Koppen kan fyldes med kaffe, smoothies, øl, vand eller suppe.</p>' ],
	[ 'eans' => [ '6411923690638' ], 'html' => '<p>Teema-kaffetragten i hvid fra Iittala er designet af Kaj Franck og har et minimalistisk udtryk. Håndtaget giver et stabilt greb, og tragten bruges til at brygge kaffe i hånden.</p>' ],
	[ 'eans' => [ '6411923690652' ], 'html' => '<p>Iittala Teema-kaffetragt i den espressofarvede nuance, designet af Kaj Franck. Den følger seriens minimalistiske stil og er en funktionel måde at brygge kaffe i hånden på.</p>' ],
	[ 'eans' => [ '6411923690645' ], 'html' => '<p>Pour-over-tragt fra Iittalas Teema-serie i en varm ravfarve. Du styrer selv vandstrømmen, så brygningen bliver jævn og præcis.</p>' ],
	[ 'eans' => [ '8721009926130' ], 'html' => '<p>To espressokopper på 120 ml fra Pip Studio, serien Lily & Lotus, hver med underkop. Elegant design til din espresso eller eftermiddagskaffe.</p>' ],
	[ 'eans' => [ '5709513364054' ], 'html' => '<p>Grand Cru termokrus fra Rosendahl på 40 cl i mørkegrå. Det er lavet af rustfrit stål og er et alternativ til to-go-kaffe i engangskrus.</p>' ],
	[ 'eans' => [ '5709846026384' ], 'html' => '<p>Bring-It er et gult to-go-krus fra Rig-Tig. Det er et miljøvenligt alternativ til papkrus med plastiklåg, og du kan tage kaffen med hjemmefra.</p>' ],
	[ 'eans' => [ '0763332074032' ], 'html' => '<p>Rise Lowball fra Klean Kanteen er en drikkekop på 296 ml i børstet rustfrit stål, lavet af 90 % genanvendt 18/8 rustfrit stål. Linjerne er bløde og ergonomiske, og farverne er hentet fra naturen.</p>' ],
	[ 'eans' => [ '5709846035805' ], 'html' => '<p>Sæt med to SR-termokrus fra Stelton, hvert på 0,2 liter. De er lavet af rustfrit stål og tegnet af Søren Refsgaard.</p><p>Designet er minimalistisk og lader stålets rå udtryk komme frem. Krusene holder varme og kolde drikke på temperatur.</p>' ],
	[ 'eans' => [ '5709846036062' ], 'html' => '<p>Keep Cool er en termoflaske på 0,6 liter fra Stelton i soft cherry. Dobbelt vakuumisolering holder drikken på temperaturen længe.</p><p>Den er lavet til lange arbejdsdage og udflugter.</p>' ],
	[ 'eans' => [ '5709846035188' ], 'html' => '<p>Stelton Keep Cool-termoflasken i soft fern green rummer 0,6 liter. Den bløde grønne farve giver et naturligt udtryk.</p>' ],
	[ 'eans' => [ '5707644926844' ], 'html' => '<p>To hvide Bistro-krus fra Nicolas Vahé med to smalle røde striber. De rummer 30 cl, har ingen hank og minder om caféstemning.</p>' ],
	[ 'eans' => [ '5707644926332' ], 'html' => '<p>Sæt med to hvide Bistro-krus på 30 cl fra Nicolas Vahé, dekoreret med to smalle blå striber. De blå striber giver diskret kontrast.</p><p>Designet er tidløst og har fransk bistro-stil.</p>' ],
	[ 'eans' => [ '7320062105639' ], 'html' => '<p>Fugl Jubilee-kruset fra Rörstrand rummer 30 cl og har en håndmalet fornemmelse. Det er en del af Rörstrands 300-års jubilæumsserie, og dekorationen er klassisk.</p>' ],
	[ 'eans' => [ '5709846034686' ], 'html' => '<p>Keep Cool fra Stelton i dark forest rummer 60 cl og er tegnet af den italienske designduo DebiasiSandri. Flasken er lavet af 90 % genanvendt stål med pulverlakering.</p>' ],
	[ 'eans' => [ '5706631162388' ], 'html' => '<p>To Go Cup fra Eva Solo i marmorgrå. Låget har klik-funktion og kan betjenes med kun én hånd, og koppen er 100 % drypfri.</p><p>Den bruges til morgenkaffe eller iste på farten.</p>' ],
	[ 'eans' => [ '5709513364030' ], 'html' => '<p>Rosendahls Grand Cru termokrus på 40 cl i farven sand. Det er fremstillet i rustfrit stål og kan erstatte engangskrus, hvis du vil spare på to-go-kaffen.</p>' ],
	[ 'eans' => [ '0699965157357' ], 'html' => '<p>Bodum Bistro er en hvid elkedel på 0,5 liter. Den slukker selv, når vandet er kogt, og kan løftes af basen.</p><p>Strømforbruget er lavet lavt.</p>' ],
	[ 'eans' => [ '5722008212364' ], 'html' => '<p>Fire krus på 30 cl fra Bitz i fire farver, med matglaseret yderside og blank inderside. Indersiderne er glaseret i rav, lilla, creme og lyserød.</p><p>Krusene er lavet af stentøj.</p>' ],
	[ 'eans' => [ '5709846035270' ], 'html' => '<p>To Go Click-termokop fra Stelton på 0,2 liter med Mumi-motivet I Love You. Dobbelt væg holder varmt i op til 2 timer og koldt i op til 4 timer.</p><p>Koppen er lavet af rustfrit stål og BPA- og phthalatfri plast.</p>' ],
	[ 'eans' => [ '5709846035317' ], 'html' => '<p>Termokoppen To Go Click fra Stelton har Mumi-motivet Courage og rummer 0,2 liter. Den holder varmt i op til 2 timer og koldt i op til 4 timer.</p><p>Materialerne er rustfrit stål og BPA- og phthalatfri plast.</p>' ],
	[ 'eans' => [ '4009839381157' ], 'html' => '<p>Sorrento er to håndblæste espressokopper på 140 ml fra Zwilling i borosilikatglas. Dobbelt væg isolerer, så drikken holder sig varm længere.</p>' ],
	[ 'eans' => [ '0032622011928' ], 'html' => '<p>To hvidvinsglas på 44 cl fra Luigi Bormioli, serien Atelier Riesling. Formen er moderne og sørger for, at aromaerne spredes godt.</p>' ],
	[ 'eans' => [ '3050910358811' ], 'html' => '<p>Krus på 30 cl fra Pillivuyt i serien Eventail, hvis mønster leder tankerne hen på elegante vifter. Stellet har en legende og sofistikeret udstråling.</p>' ],
	[ 'eans' => [ '4002458068072' ], 'html' => '<p>Alfi Kugle i mat grå på 0,94 liter. Kuglekanden blev tegnet af Ole Palsby i 1985 og har fået navnet Modern Classic No. 1. Den har vundet priser og har været udstillet på MOMA i New York.</p>' ],
	[ 'eans' => [ '4002458480928' ], 'html' => '<p>Alfi IsoTherm Eco er en termoflaske på 0,50 liter i mat rustfrit stål.</p><ul><li>Dobbeltvægget</li><li>Skruelåget kan bruges som drikkekop</li><li>Holder varmt i 12 timer</li><li>Holder koldt i 24 timer</li></ul>' ],
	[ 'eans' => [ '4002458490071' ], 'html' => '<p>Termokande i Frost Desert Grey fra Alfi, på 0,94 liter. Kuglekanden blev tegnet af Ole Palsby i 1985 og kaldes Modern Classic No. 1.</p>' ],
	[ 'eans' => [ '4002458534478' ], 'html' => '<p>Alfis kuglekande i farven Silt Green rummer 0,94 liter. Formen som kugle har den største volumen i forhold til overfladen, og det holder indholdet varmt eller koldt længe.</p><p>Designet stammer fra Ole Palsby, 1985.</p>' ],
	[ 'eans' => [ '5709513205517' ], 'html' => '<p>Hvid kop med underkop fra serien Grand Cru Soft hos Rosendahl. Koppen rummer 28 cl.</p>' ],
	[ 'eans' => [ '5709631054585' ], 'html' => '<p>To termokrus i ovnfast porcelæn fra Pillivuyt, serien Plissé, i hvid.</p><ul><li>Kapacitet: 25 cl</li><li>Højde: 12 cm</li><li>Diameter: 8 cm</li><li>2 års brudgaranti</li></ul>' ],
	[ 'eans' => [ '6411801029505' ], 'html' => '<p>24h Tuokio-kruset fra Arabia er tegnet af Heikki Orvola og har Kallio- og Helorinne-mønstret i dyb koboltblå. Kruset rummer 0,4 liter og har et enkelt formsprog, der leder tankerne hen på nordisk design.</p>' ],
	[ 'eans' => [ '0763332083829' ], 'html' => '<p>Rise Lowball er et kompakt termokrus på 237 ml i farven iceberg. Isoleringsteknologien Climate Lock holder på temperaturen, så du kan tage morgenkaffen med ud eller holde en drik kold.</p>' ],
	[ 'eans' => [ '0763332083850' ], 'html' => '<p>Termokop på 237 ml fra Klean Kanteen i dusty orchid. Climate Lock-isoleringen bevarer drikkens temperatur længe, uanset om det er varm kaffe eller en kold drik.</p>' ],
	[ 'eans' => [ '0763332083836' ], 'html' => '<p>Rise Lowball i brittany blue rummer 237 ml. Climate Lock-teknologi isolerer og holder temperaturen, uanset om du vælger en kold drik på turen eller en varm kop kaffe.</p>' ],
	[ 'eans' => [ '0763332083805' ], 'html' => '<p>Sort termokop fra Klean Kanteens Rise Lowball-serie. Kapaciteten er 237 ml, og designet er kompakt og stilrent.</p><p>Isoleringen holder varm espresso varm og kolde drikke kolde.</p>' ],
	[ 'eans' => [ '0763332083812' ], 'html' => '<p>Termokrus i barely blue fra Klean Kanteen, Rise Lowball, 237 ml. Climate Lock-isoleringen sørger for, at indholdet forbliver tempereret, uanset om det er varmt eller koldt.</p>' ],
	[ 'eans' => [ '5010576388711' ], 'html' => '<p>King-termoflasken fra Thermos i mosgrøn rummer 0,5 liter. Den kompakte størrelse gør, at den passer i køkkenet, på kontoret eller i tasken.</p><p>Konstruktionen er i rustfrit stål.</p>' ],
	[ 'eans' => [ '5709846034822' ], 'html' => '<p>THERM-IT fra Rig-Tig er en termokande på 0,9 liter i blå. Formen er retroinspireret, og farven giver borddækningen et friskt udtryk.</p>' ],
	[ 'eans' => [ '7340088509655' ], 'html' => '<p>Kaffekande fra Stabilotherm i rustfrit stål, 2 liter. Den er lavet til at brygge kaffe over bål og tåler udendørs brug. Håndtaget kan foldes.</p>' ],
	[ 'eans' => [ '5706631274296' ], 'html' => '<p>Urban-termoflasken fra Eva Solo i motivet funky ballerina rummer 0,7 liter. Størrelsen passer til arbejde, fitnesscenter og lange gåture.</p>' ],
	[ 'eans' => [ '5706631269513' ], 'html' => '<p>Eva Solo Urban på 0,7 liter i den varme farve caramel cream. Den rummelige flaske giver rigeligt at drikke på familieudflugten eller en lang dag på farten.</p>' ],
	[ 'eans' => [ '5706631269490' ], 'html' => '<p>Sort Urban-termoflaske fra Eva Solo, 0,7 liter. Den store kapacitet er tænkt til længere udflugter, lange arbejdsdage og træning.</p>' ],
	[ 'eans' => [ '3045387296858' ], 'html' => '<p>Thermo Protect fra OBH Nordica er en sort elkedel på 1,5 liter. Størrelsen er nok til morgente, kaffe efter maden eller en hurtig kop om aftenen.</p>' ],
	[ 'eans' => [ '6411255018278' ], 'html' => '<p>To Oiva-krus på 2,5 dl fra Marimekko med Unikko-blomstermønstret, hvid med karamel og orange. De kan bruges til både varme og kolde drikke, til snacks eller som opbevaring på køkkenet.</p>' ],
	[ 'eans' => [ '0699965288624' ], 'html' => '<p>Seks glaskrus på 0,35 liter fra Bodum Bistro. De kan bruges til varme og kolde drikke som kakao, te, kaffe og cocktails.</p><p>Hanken gør, at fingrene ikke brændes.</p>' ],
	[ 'eans' => [ '9355973120974' ], 'html' => '<p>Knockbox 10 fra Sage i brushed silver er en beholder til brugt kaffegrums. Du banker portafilteret mod stangen for at få kaffepucken ud uden at svine.</p><p>Der er plads til op til ti espressopucker.</p>' ],
	[ 'eans' => [ '4009839534058' ], 'html' => '<p>Thermo er en hvid termoflaske på 1 liter fra Zwilling. Den holder drikkevarer varme i op til 18 timer og kolde i op til 24 timer.</p>' ],
	[ 'eans' => [ '5709513364504' ], 'html' => '<p>Grand Cru To Go termokop fra Rosendahl på 28 cl i sand. Trykknappen gør, at du kan åbne den med én hånd.</p><p>Den holder kaffe, te eller vand varm på farten.</p>' ],
	[ 'eans' => [ '5010576347299' ], 'html' => '<p>Thermos King termokande på 0,5 liter i navy. Skruelåget behøver ikke tages af ved hældning, og låget kan bruges som krus.</p>' ],
	[ 'eans' => [ '6411254829042' ], 'html' => '<p>To Oiva-krus på 2,5 dl fra Marimekko i grøn og rød med Seireeni-mønstret, skabt af tekstilkunstneren Maija Isola efter en rejse til Grækenland i 1960\'erne. Mønstret er inspireret af havets bevægelser.</p>' ],
	[ 'eans' => [ '6411254803837' ], 'html' => '<p>Sæt med to Oiva-krus fra Marimekko, dekoreret med Seireeni-mønstret af Maija Isola. Det er opkaldt efter de mytologiske sirener.</p><p>Hvert krus rummer 2,5 dl og har farverne blå, brun og mint.</p>' ],
	[ 'eans' => [ '6411253809328' ], 'html' => '<p>Espressokop og fad fra Marimekko med sort-hvidt prikmønster af Maija Louekari. Koppen rummer et enkelt espressoshot og kommer med en hvid firkantet tallerken.</p>' ],
	[ 'eans' => [ '5709846033245' ], 'html' => '<p>Theo-termokruset fra Stelton er i sort stentøj og rummer 0,25 liter. Det leveres med bordskåner og har et minimalistisk design.</p>' ],
	[ 'eans' => [ '7340115488397' ], 'html' => '<p>Kaffekande til bål fra Hällmark med plads til 5 liter. Det tynde materiale gør, at vandet hurtigt varmes op over åben ild.</p>' ],
	[ 'eans' => [ '4977642033443' ], 'html' => '<p>Hario Cold Brew-flasken i chokoladebrun er lavet til koldbryg. Bønnerne trækker langsomt i koldt vand over flere timer eller natten over, og flasken har filter.</p><p>Resultatet kan hentes direkte fra køleskabet.</p>' ],
	[ 'eans' => [ '0745606734200' ], 'html' => '<p>Krus fra Denbys Kiln-serie i farven coral med ribbet overflade og hånddyppet glasur. Hvert krus får sin egen farvenuance, og formen er generøs.</p><p>Det kan bruges til kaffe, te, varm chokolade eller suppe.</p>' ],
	[ 'eans' => [ '0749151810099' ], 'html' => '<p>Steccato fra Spode er et krus i lertøj med smalle striber i en blå nuance. Serien findes også med mere markante striber. Designet er tidløst og enkelt.</p>' ],
	[ 'eans' => [ '5706631274272' ], 'html' => '<p>Urban-termoflasken fra Eva Solo i farven coconut rummer 0,7 liter. Den store volumen er tænkt til hele dagen, hvad enten du er på arbejde, i fitness eller på gåtur.</p>' ],
	[ 'eans' => [ '5709846034211' ], 'html' => '<p>To Go Sip fra Stelton er et sort termokrus på 40 cl med sugerør i rustfrit stål. Sugerøret gør det let at drikke undervejs.</p>' ],
	[ 'eans' => [ '5709846027756' ], 'html' => '<p>To Go Click er Steltons bud på termokoppen med skruelåg. Her i metallic sort på 0,4 liter. Koppen holder varme drikke varme i to timer og kolde drikke kolde i op til 4 timer.</p><p>Låget er udviklet med fokus på funktionalitet.</p>' ],
	[ 'eans' => [ '5709846027749' ], 'html' => '<p>Stelton To Go Click i lysegrå, 0,4 liter. Termokoppen holder varme drikke varme i to timer og kolde drikke kolde i op til 4 timer, og låget er designet til at være let at bruge.</p>' ],
	[ 'eans' => [ '0749151848276' ], 'html' => '<p>Heritage Green Italian fra Spode bygger på mærkets Blue Italian, her i dybgrøn og hvid. Kruset rummer 28 cl og kombinerer britisk håndværk med et klassisk men moderne udtryk.</p>' ],
	[ 'eans' => [ '0727015141718' ], 'html' => '<p>Chambord fra Bodum er en håndlavet stempelkande til 4 kopper, lavet af glas, massiv messing og fleksibelt rustfrit stål.</p><p>Kaffen brygges ved at trykke stemplet i bund. Bønnernes kvalitet afgør resultatet.</p>' ],
	[ 'eans' => [ '5709846035232' ], 'html' => '<p>To Go Click-termokruset fra Stelton i den lyse nuance soft chalk rummer 0,4 liter. Designet er roligt og elegant, og låget giver fleksibel brug.</p>' ],
