	[ 'eans' => [ '5703779187129' ], 'html' => '<p>Colore-kruset fra Kähler, 33 cl, i berry blue. Serien er en nyfortolkning af de dekorationsteknikker, som er udviklet på Kählers gamle keramikværksted.</p>' ],
	[ 'eans' => [ '6411801019414' ], 'html' => '<p>Underkop på 15 cm fra Mumi 80-kollektionen hos Arabia, motivet Venner for altid. Kollektionen fejrer 80-året for den første Mumi-historie, De små trolde og den store oversvømmelse.</p>' ],
	[ 'eans' => [ '5601711399121' ], 'html' => '<p>Duckpond-kruset fra Götefors Porslin, 35 cl, i porcelænsblå. Det hører til Fairytale-kollektionen, skabt med Emma von Brömssen i feldspatporcelæn.</p>' ],
	[ 'eans' => [ '7340088506265' ], 'html' => '<p>Vagabond-krus med elg fra Stabilotherm, lavet af rustfrit stål SS304. Konstruktionen er solid og tænkt til hverdag og friluftsliv.</p>' ],
	[ 'eans' => [ '7340088506937' ], 'html' => '<p>Rådyr pryder dette Vagabond-krus i rustfrit stål SS304 fra Stabilotherm. Overfladen er glat, og kruset passer til udendørsbrug.</p>' ],
