	[ 'eans' => [ '6411801025828' ], 'html' => '<p>Underkop på 15 cm til Arabias tekop, fra kollektionen Venner for evigt. Motivet bygger på Tove Janssons tegninger og hylder kærlighed, venskab og accept.</p>' ],
