	[ 'eans' => [ '6411801006391' ], 'html' => '<p>Sunnuntai-koppen fra Arabia på 28 cl er lavet i anledning af Paratiisi-seriens 50 års jubilæum. Designet af Birger Kaipiainen.</p>' ],
