	[ 'eans' => [ '4168430001007' ], 'html' => '<p>Senator er en termoflaske på 0,7 liter i stål fra Tefal/Emsa. Den har dobbeltvægget rustfrit stål og er 100 % lækagesikker.</p><ul><li>Leveres med isoleret kop</li><li>5 års garanti</li></ul>' ],
	[ 'eans' => [ '6411801003864' ], 'html' => '<p>Mumikrus fra Moomin Arabia med motivet Tro mod sin oprindelse. Porcelænskruset er ovnfast og dekoreret med figurer fra Mumidalen.</p>' ],
	[ 'eans' => [ '6411800055598' ], 'html' => '<p>Mymlen er motivet på dette ovnfaste porcelænskrus fra Moomin Arabia.</p>' ],
	[ 'eans' => [ '0083421198907' ], 'html' => '<p>Scanpan TO GO på 350 ml i Green Tea er en genanvendelig termoflaske til varme og kolde drikke. Den findes i mange farver.</p>' ],
	[ 'eans' => [ '0083421198938' ], 'html' => '<p>Scanpans TO GO-termoflaske på 350 ml i Neutral Grey. Designet fokuserer på mode, bæredygtighed og funktion, og flasken er genanvendelig.</p>' ],
	[ 'eans' => [ '0083421198969' ], 'html' => '<p>Sort TO GO fra Scanpan, 350 ml. Flasken er lavet af 100 % genanvendeligt materiale. Serien findes i 20 farver.</p>' ],
	[ 'eans' => [ '4009049226514' ], 'html' => '<p>Samba fra Tefal i hvid er en termokande på 1,0 liter. Åbn med knappen i lågets top.</p><ul><li>Højkvalitets inderglas</li><li>100 % tæt</li><li>5 års garanti</li><li>Produceret i Tyskland</li></ul>' ],
	[ 'eans' => [ '4168430002318' ], 'html' => '<p>Sort Samba-termokande fra Tefal, 1,0 liter, med Quick Tip-knap i låget.</p><ul><li>Tidløst design</li><li>100 % tæt</li><li>Højkvalitets inderglas</li><li>5 års garanti</li><li>Produceret i Tyskland</li></ul>' ],
	[ 'eans' => [ '6411801031270' ], 'html' => '<p>Lille underskål, 10 cm, fra Arabias Mainio i sarastus og hvid. Den er til Mainio-espressokoppen og er i hvidt porcelæn. Den kan stables.</p>' ],
	[ 'eans' => [ '6411255129592' ], 'html' => '<p>Oiva Unikko-kaffekoppen fra Marimekko rummer 2 dl i cranberry og pink. Den er i stentøj og tåler opvaskemaskine, ovn, mikrobølgeovn og fryser.</p>' ],
	[ 'eans' => [ '6411255129493' ], 'html' => '<p>Unikko Oiva-kruset fra Marimekko rummer 4 dl. Blomstermotivet blev skabt af Maija Isola i 1964. Farverne er hvid, beige, lys sand og mørkegrøn.</p>' ],
	[ 'eans' => [ '6411255127512' ], 'html' => '<p>Oiva-kruset med Kukasta kukkaan fra Marimekko rummer 4 dl i hvid, rosa, terracotta og blomme.</p>' ],
	[ 'eans' => [ '6411255078159' ], 'html' => '<p>Piccolo-kruset fra Marimekko på 4 dl i pære og mørkegrøn har pæregrøn glasur og mørkegrønne penselstrøg.</p>' ],
	[ 'eans' => [ '7392753570163' ], 'html' => '<p>Snefnug er en gløggkolbe på 1,3 liter fra Dorre. Den er til servering af gløgg i vintertiden.</p>' ],
	[ 'eans' => [ '4006508206056' ], 'html' => '<p>Termokop SST fra Melitta har en enkel låsefunktion mod spild og et silikonebælte. Designet er funktionelt og elegant.</p>' ],
	[ 'eans' => [ '3232870210082' ], 'html' => '<p>Troquet-espressoglas fra franske La Rochère, 10 cl, fire i pakken med fire forskellige motiver. Stilen er hentet fra klassiske franske caféer.</p>' ],
	[ 'eans' => [ '5711507019604' ], 'html' => '<p>Rhombe Color-kruset i rosa fra Lyngby Porcelæn rummer 33 cl. Serien har rene linjer og er af håndlavet porcelæn.</p>' ],
	[ 'eans' => [ '7320062104519' ], 'html' => '<p>Swedish Grace Winter-kruset fra Rörstrand rummer 50 cl. Serien er designet af Katarina Brieditis som fortolkning af Louise Adelborgs Swedish Grace og har grannåle og frosne misteltene.</p>' ],
	[ 'eans' => [ '6411801007237' ], 'html' => '<p>Misabel i gul er et af Arabias porcelænskrus fra Mumidalen. Motivet fortæller sin egen lille historie om en af Mumitroldenes venner, så kruset fungerer som både brugsting og samlerobjekt til hylden. Det er dekoreret med farvestrålende illustration og kommer fra den finske porcelænsserie, der udvides løbende med nye figurer.</p>' ],
	[ 'eans' => [ '4003686436107' ], 'html' => '<p>Afina-koppen fra Villeroy & Boch rummer 0,15 liter, altså en klassisk kaffekop i almindelig størrelse. Den er lavet af porcelæn, og det tidløse design gør, at den kan stå i selskab med mange forskellige stel. Vælg den, hvis du dækker op med små, rolige former frem for store krus.</p>' ],
	[ 'eans' => [ '6411801006100' ], 'html' => '<p>Ninni puder sidder på dette Mumikrus fra Arabia, og motivet gør det til en lille figur at drikke af. Kruset er af porcelæn og hører til serien med fortællende illustrationer fra Mumidalen. Det er oplagt som gave til en, der samler på de finske Mumitrolde, eller som et personligt hverdagskrus.</p>' ],
	[ 'eans' => [ '6411801004557' ], 'html' => '<p>Troldkarlen i lilla pryder dette krus fra Moomin Arabia. Illustrationen er hentet fra Mumidalens univers, og kruset er lavet af porcelæn med farverig dekoration. Hver figur i serien har sit eget motiv, så Troldkarlen passer til dem, der foretrækker de mere mystiske karakterer frem for de sædvanlige hovedpersoner.</p>' ],
	[ 'eans' => [ '6411253280158' ], 'html' => '<p>OIVA-kruset fra Marimekko er tegnet af Sami Ruotsalainen og har det røde Unikko-motiv. Det rummer 2,5 dl, hvilket svarer til en almindelig kop kaffe eller te. Formen er skandinavisk og enkel, og mønsteret gør kruset til det farvestærke element på bordet.</p>' ],
	[ 'eans' => [ '6419287510333' ], 'html' => '<p>Stempelkanden fra Heirol bruges ved at hælde varmt vand over malet kaffe eller te, røre rundt og sætte låget på. Kanden rummer 3,5 dl, så den passer til en lille portion til en eller to personer. Brygningen er enkel og kræver ingen filtre eller maskine.</p>' ],
	[ 'eans' => [ '7320062024374' ], 'html' => '<p>Swedish Grace i lysegrøn er et stort porcelænskrus, der rummer 50 cl. Serien blev tegnet af Louise Adelborg i 1930\'erne og har bevaret sit klassiske udtryk. Kruset tåler både opvaskemaskine og mikrobølgeovn, og kan kombineres med andre dele fra samme serie.</p>' ],
	[ 'eans' => [ '5020403061571' ], 'html' => '<p>Kruset er formet som en grøn kaktus med detaljerede former og kraftig grøn glasur. Det rummer 42 cl og er lavet til tiki-drinks og cocktails fra Genware. Det er en festlig udgave til temaaftener, hvor serveringen skal være en del af stemningen.</p>' ],
	[ 'eans' => [ '5020229110132' ], 'html' => '<p>Islander er et keramisk tiki-krus fra Beaumont, som rummer 450 ml. Det er beregnet til drinks i hawaiistil og til temafester, hvor detaljerne tæller. Kruset passer i baren eller på et sommerbord, hvor du vil have en eksotisk stemning.</p>' ],
	[ 'eans' => [ '6411800055949' ], 'html' => '<p>Hattifnatterne er motivet på dette Mumikrus fra Arabia. Kruset er af porcelæn og dekoreret i serien af illustrerede krus, der både kan bruges dagligt og stilles frem som samling.</p>' ],
	[ 'eans' => [ '5713524043341' ], 'html' => '<p>Yake-koppen fra Muubs er i farven blush og hører til en serie inspireret af japansk keramik. Koppen er håndlavet i stentøj og har et rustikt, men moderne udtryk. Da hver kop er lavet i hånden, kan der være små forskelle i glasur og form.</p>' ],
	[ 'eans' => [ '5709513203810' ], 'html' => '<p>Sættet består af to hvide krus fra Rosendahl Grand Cru. Krusene har hank og et enkelt design, som er nemt at kombinere med andet stel, hvis der skal dækkes op til flere gæster. De egner sig til kaffe og te.</p>' ],
	[ 'eans' => [ '5711507019659' ], 'html' => '<p>Rhombe Color-kruset fra Lyngby Porcelæn i gul rummer 33 cl og er lavet i håndlavet porcelæn med rene linjer. Serien findes i 7 farver, og den gule giver et solrigt indslag på morgenbordet. Ret enkelt i formen, kraftigt i farven.</p>' ],
	[ 'eans' => [ '5711507019642' ], 'html' => '<p>Den grønne udgave af Rhombe Color fra Lyngby Porcelæn rummer 33 cl. Kruset er håndlavet porcelæn med klare linjer og et enkelt mønster. Serien fås i 7 farver, så du kan vælge én for hver person i husstanden eller blande dem på bordet.</p>' ],
	[ 'eans' => [ '5711507019628' ], 'html' => '<p>Blå Rhombe Color-krus fra Lyngby Porcelæn har plads til 33 cl. Det er lavet af håndlavet porcelæn og kendes på de rene linjer og stærke farver. Serien findes i 7 forskellige farver, og den blå passer godt sammen med de øvrige i rækken.</p>' ],
	[ 'eans' => [ '6411801012200' ], 'html' => '<p>ABC Mumin-kruset fra Moomin Arabia har en stor hank og rummer 0,4 liter, så det passer til mange drikkevarer. Det fås med forskellige mønstre, og motivet er hentet fra Mumidalen. Kruset er til dem, der vil have et stort krus med børnevenligt tema.</p>' ],
	[ 'eans' => [ '7320062103826' ], 'html' => '<p>Daga-koppen fra Rörstrand rummer 33 cl og er lavet af varmebestandigt stentøj i et minimalistisk design. Farverne er mættede og inspireret af ler fra Kullabygden i Sverige. Serien kommer fra Höganäs Keramik, og modellen her hedder horisont.</p>' ],
	[ 'eans' => [ '6411801009279' ], 'html' => '<p>Filifjonkan er heltinden på dette Mumikrus fra Arabia. Hun har tre børn og laver gang på gang pudsige ting i Mumidalen. Kruset er af porcelæn og egner sig til varm te eller hyldesaft, og motivet gør det til en lille samlerting.</p>' ],
	[ 'eans' => [ '4168430000987' ], 'html' => '<p>Senator-termoflasken på 0,5 liter har dobbeltvægget rustfrit stålforing og er lækagesikker. Der følger en isoleret kop med, så du kan hælde op direkte fra flasken. Producenten giver 5 års garanti, og den er bygget til at tåle hverdagens brug.</p>' ],
	[ 'eans' => [ '6411255127574' ], 'html' => '<p>Kurre-motivet på dette krus fra Marimekko ligger på Sami Ruotsalainens Oiva-form og rummer 2,5 dl. Farverne er hvid, brun, sort og lyseblå. Marimekko er kendt for kreativt mønsterdesign, og kruset er et eksempel på det i en lille størrelse.</p>' ],
	[ 'eans' => [ '6411255125556' ], 'html' => '<p>Tiiliskivi-mønsteret på dette Oiva-krus er skabt af Marimekkos grundlægger Armi Ratia som en hyldest til hverdagens skønhed. Kruset er af stentøj i kastanjebrun og rummer 4 dl. Det passer til dem, der vil have stor kop med historie og tydeligt grafisk udtryk.</p>' ],
	[ 'eans' => [ '5606739983703' ], 'html' => '<p>Rafaela-kruset i grøn fra Costa Nova er håndlavet i stentøj i Portugal. Det har et malet mønster af fine prikker og rummer 49,4 cl. Den grønne nuance giver et friskt og moderne udtryk på bordet.</p>' ],
	[ 'eans' => [ '5606739983697' ], 'html' => '<p>Costa Novas Rafaela-krus i blå er håndlavet i stentøj i Portugal og pyntet med fine, malede prikker. Den blå farve er frisk og moderne. Kruset er velegnet til drikke i store portioner og kan bruges sammen med andre farver i serien.</p>' ],
	[ 'eans' => [ '6411801002270' ], 'html' => '<p>Too-ticky i violet er motivet på dette Mumikrus. Figuren er en af de mere kendte personer fra Mumidalen. Kruset er af porcelæn fra Arabia og dekoreret i serien, hvor hvert krus fortæller sin egen historie.</p>' ],
	[ 'eans' => [ '7315082003256' ], 'html' => '<p>Kaffekedlen 27 Small fra Trangia er lav, 7 cm høj, og har en diameter på 13,4 cm. Den er af aluminium med trådhåndtag og aftageligt plastdæksel og passer til Trangia-køkkener i størrelsen 27 Small. Den rummer 0,6 liter og er beregnet til friluftskøkkenet.</p>' ],
	[ 'eans' => [ '6411801006834' ], 'html' => '<p>Sov godt er navnet på dette Mumikrus fra Arabia. Motivet giver kruset en rolig stemning, og det passer derfor til aftenens te eller kakao. Det er lavet af porcelæn og hører til de dekorerede krus fra Mumidalen.</p>' ],
	[ 'eans' => [ '4003686436121' ], 'html' => '<p>Afina-espressokoppen fra Villeroy & Boch rummer 5 cl og er lavet af porcelæn. Den lille størrelse passer til en intens espresso. Formen er elegant og enkel, og koppen kan bruges sammen med andre dele i Afina-serien.</p>' ],
	[ 'eans' => [ '6411254970096' ], 'html' => '<p>Puutarhakutsut-mønsteret på denne Oiva-kop fra Marimekko er inspireret af en havefest med blomster og frodige blade. Koppen rummer 2 dl, og er dermed et valg til almindelig kaffe. Motivet giver bordet en sommerlig og naturnær stemning.</p>' ],
	[ 'eans' => [ '7350101310380' ], 'html' => '<p>Kruset fra Kockums Jernverk i creme har et enkelt og tidsløst design. Det kan bruges til morgenkaffe eller eftermiddagste og fungerer også som gaveidé. Den neutrale farve passer til mange slags borddækning.</p>' ],
	[ 'eans' => [ '7320062024350' ], 'html' => '<p>Swedish Grace-kruset i hvid fra Rörstrand rummer 50 cl og har et simpelt, klassisk mønster. Serien er designet af Louise Adelborg i 1930. Kruset tåler opvaskemaskine og er velegnet til dem, der drikker i større portioner.</p>' ],
	[ 'eans' => [ '4977642010062' ], 'html' => '<p>V60 Drip-Assist-sættet fra Hario er udviklet sammen med World Barista Champion Pete Licata. Designet gør det muligt at hælde vandet jævnt og ensartet over kaffen, så ekstraktionen bliver mere kontrolleret. Sættet er til dem, der brygger pour over og vil have mere ro i hældningen.</p>' ],
	[ 'eans' => [ '7340194830391' ], 'html' => '<p>Elba-kruset fra Tell Me More er i en blød grøn nuance med mat overflade. Farven giver et naturnært udtryk, og kruset passer til kaffe, te eller varm chokolade. Det er et enkelt og roligt krus til hverdagsbrug.</p>' ],
	[ 'eans' => [ '6411800185905' ], 'html' => '<p>Mymlens mor er motiv på dette Mumikrus fra Arabia. Kruset er af porcelæn og dekoreret med en figur fra Mumidalens univers. Hver figur i serien har sit krus, så Mymlens mor passer til samlere, der allerede har søsteren.</p>' ],
	[ 'eans' => [ '5706631209830' ], 'html' => '<p>Nordic Kitchen-koppen fra Eva Solo kommer med underkop og er lavet af stentøj med et rustikt udseende. Både kop og underkop kan stables, så de fylder lidt i skabet. Alle dele tåler opvaskemaskine, og koppen rummer 20 cl.</p>' ],
	[ 'eans' => [ '6411801009248' ], 'html' => '<p>Mumimor pryder dette krus fra Arabia, og det matcher Mumiskålene og Mumitallerkenerne i samme serie. Porcelænsserien egner sig både som samling og som gave. Kruset er dekoreret med fantasifuldt motiv fra Mumidalen.</p>' ],
	[ 'eans' => [ '6411254236949' ], 'html' => '<p>OIVA-kruset i siirtolapuutarha fra Marimekko rummer 4 dl og har et iøjnefaldende mønster. Størrelsen er god til kaffe, te eller kakao. Mønsteret er et blikfang på bordet, og kruset ses ofte på billeder i blogs og magasiner.</p>' ],
	[ 'eans' => [ '4003686198579' ], 'html' => '<p>Underkoppen fra Villeroy & Bochs Toy\'s Delight-kollektion er hvid, har en diameter på 19 cm og er lavet af porcelæn. Den hører til julekollektionen og passer til kaffe- eller tekop i samme serie. Brug den, hvis du vil samle et julebord med ensartet stil.</p>' ],
	[ 'eans' => [ '4012436475129' ], 'html' => '<p>Loft-kruset fra Rosenthal rummer 38 cl og kan stables, hvilket sparer plads i skabet. Serien er elegant og stilren, og kruset er nemt at kombinere med andet service. Det er praktisk for alle, der har en lille køkkenskuffe.</p>' ],
	[ 'eans' => [ '6411801006094' ], 'html' => '<p>Mumitrolden i græsgrøn er motiv på dette krus fra Moomin Arabia. Det er den centrale figur fra Mumidalen, og kruset er af porcelæn. Det er oplagt som første krus i en samling.</p>' ],
	[ 'eans' => [ '3050910247146' ], 'html' => '<p>Plissé-kruset fra Pillivuyt rummer 27 cl og har fine plisserede linjer, som stammer fra nogle af fabrikkens tidlige støbeforme fra begyndelsen af 1900-tallet. Serien fås i to farver, og designet er klassisk og elegant.</p>' ],
	[ 'eans' => [ '5709554154843' ], 'html' => '<p>RAW-termoflasken fra Aida er lavet af stål og rummer 0,5 liter. Den er i sort mat udførelse og beregnet til at tage med i bussen, på arbejde, på skovtur eller i bilen. Flasken er en del af RAW-serien.</p>' ],
	[ 'eans' => [ '5703779190808' ], 'html' => '<p>Hammershøi-kruset fra Kähler er den mindre udgave af det klassiske krus og rummer 25 cl. Det er af porcelæn i hvid og passer til kaffe, varm kakao eller te. Formen følger resten af Hammershøi-serien.</p>' ],
	[ 'eans' => [ '7340194808109' ], 'html' => '<p>Granada-koppen fra Tell Me More er håndlavet af 100 % stentøj med halvblank, cremehvid til beige glasur. Den reaktive glasering gør, at farven skifter under brændingen, så hver kop får sine nuancer. Koppen er derfor aldrig helt ens.</p>' ],
	[ 'eans' => [ '8004399324893' ], 'html' => '<p>Cappuccinoglassene fra De\'Longhi leveres to ad gangen og rummer 270 ml. De er dobbeltvæggede, så drikken holdes varm, og designet viser lagene i kaffen. De passer til cappuccino og latte.</p>' ],
	[ 'eans' => [ '7315082003249' ], 'html' => '<p>Kaffekanden 25 Large fra Trangia er en lav model med låg af aluminium. Den har trådgreb med aftagelig plastbeskyttelse og passer til Trangia-køkkener i størrelsen 25 Large. Diameteren er 15,2 cm, og kanden rummer 0,9 liter.</p>' ],
	[ 'eans' => [ '7320062102928' ], 'html' => '<p>Ostindia i sort fra Rörstrand er et krus på 40 cl i porcelæn. Serien er skabt ud fra et stykke østindisk porcelænsskår, som blev reddet med lasten fra et forlist skib. Det giver kruset en særlig historie.</p>' ],
	[ 'eans' => [ '4024472145768' ], 'html' => '<p>Melitta Pyramiden 202 S er kaffefiltre med ekstra stærke dobbelte sømme. De er 100 % kompostable og giver aroma fra friskbrygget kaffe. Filtrene bruges til filterbrygning i en holder af typen 202.</p>' ],
	[ 'eans' => [ '4168430011778' ], 'html' => '<p>Compact-termokruset fra Tefal er sort, rummer 0,3 liter og har twist-to-open-låg. Det er 100 % tæt, holder drikken varm i 3 timer og kold i 6 timer. Højden er 15 cm og diameteren 7,2 cm.</p>' ],
	[ 'eans' => [ '4168430011792' ], 'html' => '<p>Termokruset i grøn fra Tefal Compact rummer 0,3 liter og har et låg, der åbnes med et twist. Kruset er 100 % tæt og holder varmen i 3 timer og kulden i 6 timer. Det måler 15 cm i højden og 7,2 cm i diameter.</p>' ],
	[ 'eans' => [ '5709846016026' ], 'html' => '<p>Theo-koppen fra Stelton er i sort stentøj og kommer med en coaster af bambus. Den rummer 0,2 liter og måler 8 cm i både højde og diameter. Coasteren er lavet af bæredygtig bambus og fungerer som underkop.</p>' ],
	[ 'eans' => [ '6411923690447' ], 'html' => '<p>Teema-kruset fra Iittala i farven espresso er et krus på 0,3 liter. Den jordnære, mørke tone gør, at det er let at kombinere med resten af stellet. Kruset passer til både lyse og neutrale farver.</p>' ],
	[ 'eans' => [ '6411923690430' ], 'html' => '<p>Teema-kruset i rav rummer 0,3 liter og er fra Iittala. Den bløde, varme nuance minder om bærnsten og kan kombineres med både minimalistisk og farvet service. Det er et almindeligt krus til kaffe, te eller varm chokolade.</p>' ],
	[ 'eans' => [ '6411255152033' ], 'html' => '<p>Unikko Oiva-kruset fra Marimekko rummer 2,5 dl og bærer det ikoniske valmueprint, som Maija Isola skabte i 1960\'erne. Farverne er hvid, mørkegrøn, beige og sand. Kruset passer til morgenkaffe eller eftermiddagste.</p>' ],
	[ 'eans' => [ '6411255129509' ], 'html' => '<p>Dette Unikko-krus fra Marimekko rummer 25 cl og har Maija Isolas blomsterprint i hvid, beige, sand og mørkegrøn. Printet blev skabt i en tid, hvor Marimekkos kollektioner mest bestod af abstrakte tryk. Kruset bærer dermed en del finsk designhistorie.</p>' ],
	[ 'eans' => [ '6411255078142' ], 'html' => '<p>Piccolo-kruset fra Marimekko rummer 2,5 dl og har håndmalede striber i pæregrøn og mørkegrøn. Mønsteret giver rytme og energi på bordet. Kruset egner sig til kaffe og te.</p>' ],
	[ 'eans' => [ '6411255076209' ], 'html' => '<p>Piccolo-kruset i sort og hvid fra Marimekko har plads til 4 dl. Det grafiske mønster giver et skarpt udtryk, og størrelsen gør det til et valg for dem, der drikker kaffe, te eller kakao i store portioner.</p>' ],
	[ 'eans' => [ '6411255017905' ], 'html' => '<p>Iso Unikko-kruset fra Marimekko er en del af Oiva-serien, formgivet af Sami Ruotsalainen. Det rummer 4 dl og er dekoreret med Maija Isolas ikoniske blomstermotiv i hvid og beige. Kombinationen giver et krus med et tydeligt grafisk udtryk.</p>' ],
	[ 'eans' => [ '5712195044589' ], 'html' => '<p>Mellow-børnekrusene fra OYOY Mini er en 2-pak i cherry red og vanilla. De er lavet af 100 % silikone og formet med inspiration fra bløde skumfiduser. Krusene er designet til små hænder.</p>' ],
	[ 'eans' => [ '7394150185728' ], 'html' => '<p>Sagaform Coffee & More er fire espressokopper i beige stentøj. De er dekoreret med et reliefmønster, der giver en fornemmelse af overfladen. Sættet passer til dem, der serverer espresso til flere.</p>' ],
	[ 'eans' => [ '9312432028165' ], 'html' => '<p>Claris-filteret fra Sage renser vandet i espressomaskinen og reducerer kalk. Det passer til alle modeller, hvor filteret ligner i forvejen. Tjek, at din maskine har samme type, før du bestiller.</p>' ],
	[ 'eans' => [ '0727015530291' ], 'html' => '<p>Pavina-glassene fra Bodum er espressoglas i dobbeltvægget glas, formet som små halvovale former. Det dobbelte lag holder på varmen, så du ikke brænder fingrene. Hvert glas rummer 0,08 liter, og sættet består af to stykker.</p>' ],
	[ 'eans' => [ '7394150001158' ], 'html' => '<p>Liz-kruset fra svenske Byon er i stentøj med et chunky, dristigt udtryk. Denne udgave er ternet i blå og hvid. Kollektionen findes i flere mønstre med både dæmpede toner og stærke farver, så kruset kan vælges efter stil.</p>' ],
	[ 'eans' => [ '7394150001141' ], 'html' => '<p>Her er Liz-kruset fra Byon i stribet grøn og hvid. Det er fremstillet af stentøj og har en kraftig, frisk form. Serien er svensk, og mønstrene spænder fra dæmpede toner til stærke farver, så striberne kan stå alene eller blandes med andre udgaver.</p>' ],
	[ 'eans' => [ '7394150183700' ], 'html' => '<p>Coffee & More fra Sagaform er skabt sammen med designeren Margot Barolo. Her får du to grønne kaffekrus med karakteristisk relief. Serien er inspireret af 70\'erne, og krusene fungerer som små kunstværk på bordet.</p>' ],
	[ 'eans' => [ '6411800072403' ], 'html' => '<p>Teema-kruset fra Iittala rummer 40 cl og er i hvid. Serien er tegnet af den finske designer Kaj Franck og består af porcelænsprodukter fra tallerkener til krus. Iittala forarbejder materialet grundigt, og de enkle former passer sammen med mange typer stel.</p>' ],
	[ 'eans' => [ '6411254175835' ], 'html' => '<p>Dette OIVA-krus fra Marimekko rummer 4 dl og bærer mønsteret räsymatto. Det er et stort krus til kaffe, te eller kakao. Mønsteret er et blikfang, og kruset ses ofte i magasiner og på blogs.</p>' ],
	[ 'eans' => [ '7320062025609' ], 'html' => '<p>Swedish Grace i Rose-udgaven er et krus på 50 cl i porcelæn. Serien blev tegnet af Louise Adelborg i 1930\'erne. Kruset kan vaskes i opvaskemaskine og bruges i mikrobølgeovn, og det kan sættes sammen med andre dele fra serien.</p>' ],
	[ 'eans' => [ '7320062024367' ], 'html' => '<p>Blå/grå Swedish Grace-krus fra Rörstrand rummer 50 cl og er af porcelæn. Det stilrene design stammer fra Louise Adelborg i 1930\'erne. Kruset tåler både opvaskemaskine og mikrobølgeovn.</p>' ],
	[ 'eans' => [ '5010853233314' ], 'html' => '<p>Latteglassene fra Ravenhead Entertain kommer i sæt med to klare glas på 26 cl. De viser lagene i kaffe og andre varme drikke. Mængden passer til en latte eller varm kakao.</p>' ],
	[ 'eans' => [ '4977642222564' ], 'html' => '<p>Dette isolerede termokrus fra Hario rummer 300 ml og har en grå finish. Designet er japansk og funktionelt, og det kommer med låg. Kruset er lavet til at tage friskbrygget kaffe med på kontoret, i bilen eller på gåturen.</p>' ],
	[ 'eans' => [ '5020229110163' ], 'html' => '<p>Coconut Tiki-kruset fra Beaumont er formet som en kokosnød i brun finish. Det er keramisk og rummer 500 ml. Det passer til tropiske drinks og lounge-stemning ved festen.</p>' ],
	[ 'eans' => [ '5709513210412' ], 'html' => '<p>Cottage-kruset i Rosendahls Grand Cru-serie rummer 30 cl. Det er det hvide Grand Cru-krus, men med en efterårsagtig dekoration. Det skaber varme stunder i de kolde måneder.</p>' ],
	[ 'eans' => [ '5709513201960' ], 'html' => '<p>Rhombe Color i mørkeblå fra Lyngby Porcelæn rummer 33 cl. Kruset er håndlavet porcelæn med rene linjer og et simpelt mønster. Serien er udformet i 7 farver, og den mørkeblå er den dybe nuance i rækken.</p>' ],
	[ 'eans' => [ '3050910236195' ], 'html' => '<p>Plissé-koppen fra Pillivuyt rummer 29 cl og kan bruges til kaffe, te eller varm chokolade. Koppen fås i flere størrelser, så du kan vælge efter behov. Serien er kendt for sine plisserede linjer og tidløse udtryk.</p>' ],
	[ 'eans' => [ '5709513364535' ], 'html' => '<p>To Go-koppen fra Rosendahl i mørkegrå har en trykknapfunktion, der gør den let at åbne med én hånd. Et silikonebånd giver et godt greb, og der er en hændeflade på 363 gr., så du kan drikke fra alle vinkler. Den er lavet til at tage med.</p>' ],
	[ 'eans' => [ '5711507019673' ], 'html' => '<p>Rhombe Color-kruset fra Lyngby Porcelæn i turkis rummer 33 cl. Det er håndlavet porcelæn med klare linjer og stærk farve. Det er en af 7 farver i serien.</p>' ],
	[ 'eans' => [ '5711507012353' ], 'html' => '<p>Det hvide Rhombe-krus fra Lyngby Porcelæn rummer 33 cl og er håndlavet porcelæn. Rene linjer og enkelt mønster er seriens kendetegn. Hvid er den neutrale i rækken af 7 farver, og den passer til de andre.</p>' ],
	[ 'eans' => [ '5703779160610' ], 'html' => '<p>Hammershøi-kruset fra Kähler rummer 33 cl og er i klassisk hvid. Det kan bruges til kaffe eller aromatisk te. Kruset passer sammen med resten af Hammershøi-serien.</p>' ],
	[ 'eans' => [ '4003762296731' ], 'html' => '<p>Noblesse Barista-glassene fra Nachtmann kommer to ad gangen og er til espresso, doppio og ristretto. Den slanke form og en let indadbøjet kant hjælper med at bevare cremaen. De er klare og lavet til at fremhæve aroma og smag.</p>' ],
	[ 'eans' => [ '5706631206440' ], 'html' => '<p>Termokaffekoppen fra Eva Solo i farven Lemon drop er en del af Nordic Kitchen-serien. Den har et minimalistisk design og er beregnet til at tage kaffe med på arbejde eller gåturen. Koppen er isoleret.</p>' ],
	[ 'eans' => [ '7340194804286' ], 'html' => '<p>Bon-kruset fra Tell Me More er i stentøj med mat finish og i størrelsen small. Stentøjet gør, at hvert krus er unikt i form, farve og følelse. Udtrykket er rustikt.</p>' ],
	[ 'eans' => [ '7340115488335' ], 'html' => '<p>Kaffekanden fra Hällmark rummer 1,5 liter og er lavet til brug over åben ild, for eksempel på bål eller i haven på ildstedet. Den er beregnet til camping og teltture, hvor kaffen skal koges udenfor.</p>' ],
	[ 'eans' => [ '5711173331123' ], 'html' => '<p>Claire-koppen fra Bloomingville er i grå stentøj og har påskriften "Stay magical". Koppen er lavet til rolige pauser og har et hyggeligt udtryk.</p>' ],
	[ 'eans' => [ '5711173340590' ], 'html' => '<p>Shine-koppen fra Bloomingville er i stentøj med glitrende sølvfarvet overflade. Den kan bruges til hverdagen og til særlige lejligheder.</p>' ],
	[ 'eans' => [ '4004094247361' ], 'html' => '<p>Dette erstatningsglas på 1000 ml passer til Westmark Brasilia stempelkanden. Er glasset gået i stykker, kan du udskifte det i stedet for at købe en ny kande. Det er til Brasilia fra Royal Series.</p>' ],
	[ 'eans' => [ '4006508173082' ], 'html' => '<p>Melitta-stempelkanden på 3 kopper laver kaffe i fransk stil. Brug grovmalet kaffe, hæld varmt vand over, og lad det trække, så du får en fyldig smag. Kanden er lille og passer til en eller to personer.</p>' ],
	[ 'eans' => [ '3050910236188' ], 'html' => '<p>Plissé-koppen fra Pillivuyt på 18 cl har en diameter på 8,5 cm. Den passer til kaffe, te og varm chokolade. Mønstret med plisserede linjer er klassisk, og formen stammer fra tidlige støbeforme fra 1900-tallet.</p>' ],
	[ 'eans' => [ '5713524046465' ], 'html' => '<p>Mame-koppen fra Muubs rummer 40 cl og er i en kaffefarvet glasur. Serien er inspireret af naturens organiske former og kombinerer moderne udtryk med rustikke detaljer. Hver kop er lavet med traditionelle keramiske teknikker.</p>' ],
	[ 'eans' => [ '7320062103789' ], 'html' => '<p>Daga-kruset fra Rörstrand rummer 30 cl og er i farven sand. Det er af robust stentøj, og designet er elegant og minimalistisk. Farven er inspireret af ler fra Kullabygden.</p>' ],
	[ 'eans' => [ '7320062103819' ], 'html' => '<p>Daga-koppen i sand fra Rörstrand rummer 33 cl og er lavet af varmebestandigt stentøj. Designet er minimalistisk. Farven er hentet fra leret i Kullabygden.</p>' ],
	[ 'eans' => [ '7320062103642' ], 'html' => '<p>Swedish Grace i farven dimma er et 50 cl porcelænskrus fra Rörstrand. Louise Adelborg tegnede serien i 1930\'erne. Du kan vaske kruset i maskine og bruge det i mikrobølgeovn.</p>' ],
	[ 'eans' => [ '6411255076254' ], 'html' => '<p>Unikko-kaffekoppen fra Marimekko rummer 2 dl og er i hvid, ler og rød. Den er en god størrelse til espresso eller sort kaffe. Koppen har det kendte blomstermotiv.</p>' ],
	[ 'eans' => [ '6411255076353' ], 'html' => '<p>Unikko-kaffekoppen i sort og hvid fra Marimekko rummer 2 dl. Den har det ikoniske blomstermotiv i et stilrent, grafisk udtryk. Koppen er til den lille portion kaffe.</p>' ],
	[ 'eans' => [ '6411255017868' ], 'html' => '<p>Kukat Puhkeava er navnet på mønsteret på dette Oiva-krus fra Marimekko. Kruset rummer 2,5 dl og er i hvid, grøn og sort. Det kan bruges til kaffe, te eller kakao.</p>' ],
	[ 'eans' => [ '7394150185674' ], 'html' => '<p>Inka-koppen fra Sagaform rummer 27 cl og er i stentøj. Den har en rundet bund og en robust kant med Sagaforms karakteristiske rille. Koppen passer til kaffe, te eller varm kakao.</p>' ],
	[ 'eans' => [ '7394150185360' ], 'html' => '<p>Inka-kruset i vinrød fra Sagaform rummer 27 cl. Det er af stentøj med afrundet base og robust øre, så grebet er behageligt. Den rillede detalje er seriens kendetegn.</p>' ],
	[ 'eans' => [ '7394150185353' ], 'html' => '<p>Gul Inka-krus fra Sagaform rummer 27 cl og er i stentøj. Basen er rundet, øret er robust, og overfladen har seriens rillede detalje. Det er et krus til daglig kaffe eller te.</p>' ],
	[ 'eans' => [ '7394150185346' ], 'html' => '<p>Det grå Inka-krus fra Sagaform rummer 27 cl. Stentøjet har en afrundet base, robust øre og rillet dekoration. Den grå farve er neutral i hverdagen.</p>' ],
	[ 'eans' => [ '7394150185339' ], 'html' => '<p>Hvid Inka fra Sagaform er et 27 cl krus i stentøj. Det har et robust øre og en harmonisk, rundet base. Rillerne er seriens kendetegn.</p>' ],
	[ 'eans' => [ '7394150185322' ], 'html' => '<p>Sort Inka-krus fra Sagaform rummer 27 cl og er lavet af stentøj. Det har en rundet base og et kraftigt øre. Overfladen har seriens rillede mønster.</p>' ],
	[ 'eans' => [ '7394150185315' ], 'html' => '<p>Beige Inka-krus fra Sagaform rummer 27 cl og er i stentøj. Formen er rundet i bunden, og øret giver et behageligt greb. Seriens rillede detalje er med.</p>' ],
	[ 'eans' => [ '7320062104076' ], 'html' => '<p>Swedish Grace i havre fra Rörstrand rummer 50 cl. Serien er designet af Louise Adelborg og er en hyldest til det svenske landskab. Den varme havrefarve giver et blødt udtryk.</p>' ],
	[ 'eans' => [ '6411923672382' ], 'html' => '<p>Teema-kruset fra Iittala i linen rummer 40 cl. Serien er designet af Kaj Franck og består af porcelænsprodukter. De enkle former passer sammen med mange stel.</p>' ],
	[ 'eans' => [ '7320062102645' ], 'html' => '<p>Mon Amie-underkoppen fra Rörstrand har en diameter på 13 cm. Mønstret er baseret på planten mosepost og blev tegnet af Marianne Westman. Det hører til en af hendes store successer.</p>' ],
	[ 'eans' => [ '7320062100917' ], 'html' => '<p>Swedish Grace Vinter er et krus på 30 cl i porcelæn fra Rörstrand. Det kan bruges både til morgenkaffe og eftermiddagste. Serien er tegnet af Louise Adelborg i 1930\'erne.</p>' ],
	[ 'eans' => [ '6411800162388' ], 'html' => '<p>Teema i perlegrå rummer 40 cl og kommer fra Iittala. Kaj Franck designede serien, som består af porcelænsprodukter. Farven er afdæmpet og passer til andre dele af Teema.</p>' ],
	[ 'eans' => [ '6411800072557' ], 'html' => '<p>Teema-kruset i hvid fra Iittala rummer 30 cl. Serien er designet af Kaj Franck med vægt på det simple og universelle. Derfor passer produkterne ind i mange køkkener og sammen med andre typer stel.</p>' ],
	[ 'eans' => [ '6411254832691' ], 'html' => '<p>Dette store OIVA-krus fra Marimekko rummer 40 cl i off white og er dekoreret med Unikko-valmuemønsteret. Maija Isola designede mønsteret i 1960\'erne, og det er et af Marimekkos populære motiver.</p>' ],
	[ 'eans' => [ '7320062025593' ], 'html' => '<p>Swedish Grace i Rose er et krus på 30 cl fra Rörstrand. Det er af porcelæn og til morgenkaffe eller eftermiddagste. Serien er tegnet af Louise Adelborg i 1930\'erne.</p>' ],
	[ 'eans' => [ '7320061192135' ], 'html' => '<p>Lysegrønt Swedish Grace-krus på 30 cl fra Rörstrand. Porcelænet er designet af Louise Adelborg i 1930\'erne, og kruset kan bruges til både kaffe og te.</p>' ],
	[ 'eans' => [ '7320061191831' ], 'html' => '<p>Blå/grå Swedish Grace fra Rörstrand rummer 30 cl. Kruset er i porcelæn og egner sig til kaffe og te. Louise Adelborg designede serien i 1930\'erne.</p>' ],
	[ 'eans' => [ '5711173331130' ], 'html' => '<p>Claire-koppen i hvidt stentøj fra Bloomingville har påskriften "Lots of love". Den er lavet til rolige kaffepauser og teunder. Udtrykket er enkelt.</p>' ],
	[ 'eans' => [ '5711173331147' ], 'html' => '<p>Claire-koppen i brun stentøj fra Bloomingville har teksten "Enjoy every moment". Den er lavet til hyggelige stunder og har et personligt, afslappet udtryk.</p>' ],
	[ 'eans' => [ '4977642031661' ], 'html' => '<p>SUIREN-rib-sættet fra Hario består af 6 ribs i transparent pink. Det er modulært og kan bruges til at tilpasse eller forny udtrykket på din manuelle V60-brygger.</p>' ],
	[ 'eans' => [ '8718215103714' ], 'html' => '<p>TwoFace-krus fra Barprofessional rummer 400 ml og har et dobbeltansigtet tiki-motiv med stirrende øjne og åbne munde. Det er lavet til tiki-cocktails og vil skille sig ud i baropsætningen.</p>' ],
	[ 'eans' => [ '5722000343875' ], 'html' => '<p>Shoku-kruset fra Villa Collection rummer 33 cl og har hank. Stentøjet har en silkemat overflade i soft beige. Designet er enkelt og stilfuldt.</p>' ],
	[ 'eans' => [ '5709513251682' ], 'html' => '<p>Grand Cru Soft-latteglassene fra Rosendahl bruges til café latte, men kan også anrette dekorative forretter og desserter. Glassene har en rund kant.</p>' ],
	[ 'eans' => [ '6411253279527' ], 'html' => '<p>OIVA-kaffekoppen fra Marimekko rummer 2 dl og er af solidt stentøj med hank. Designet er tegnet af Sami Ruotsalainen, og motivet er unikko i rød. Koppen tåler opvaskemaskine.</p>' ],
	[ 'eans' => [ '3272340049484' ], 'html' => '<p>Dining Line-kruset fra Staub rummer 350 ml i farven white truffle med perlemorskimrende glasur. Det kan bruges til kaffe, te, varm chokolade eller suppe.</p>' ],
	[ 'eans' => [ '4003686436114' ], 'html' => '<p>Underkoppen fra Villeroy & Boch Afina har en diameter på 14 cm og passer til kaffekoppen i serien. Formen er elegant og funktionel, og den fuldender kopsættet.</p>' ],
	[ 'eans' => [ '6411801004670' ], 'html' => '<p>Mainio fra Arabia er en alsidig servise-serie, og denne kop i farven sarastus rummer 0,17 liter. Serien findes i to størrelser, 0,17 og 0,4 liter, og koppene kan bruges til varme drikke, men også til smoothies eller suppe. Den lille størrelse passer til kaffe.</p>' ],
	[ 'eans' => [ '5020403172758' ], 'html' => '<p>Skull Tiki-kruset fra Genware har et markant dødningehoved og en mat, struktureret overflade, der efterligner støbejern. Det rummer 80 cl, svarende til 28,15 oz, og er beregnet til cocktails med dramatisk udtryk i baren eller ved bordet.</p>' ],
	[ 'eans' => [ '5711173299171' ], 'html' => '<p>Sandrine-kruset i grå stentøj fra Bloomingville rummer 50 cl. Serien har et rustikt og naturligt udtryk, og kruset er rummeligt nok til en rigtig stor portion kaffe eller te.</p>' ],
	[ 'eans' => [ '5706631165433' ], 'html' => '<p>Koppen fra Eva Solo Nordic Kitchen har en enkel form og en varm sort nuance. Den kan bruges til hverdag og behøver ikke gemmes til fine lejligheder. Den er en del af serien, så den passer sammen med resten af Nordic Kitchen.</p>' ],
	[ 'eans' => [ '7350101310403' ], 'html' => '<p>Kruset fra Kockums Jernverk i hvid er enkelt og tidsløst i designet. Det kan bruges til morgenkaffe og eftermiddagste og er en mulig gaveidé. Hvid farve gør det let at stille på ethvert bord.</p>' ],
	[ 'eans' => [ '0763332085366' ], 'html' => '<p>Rise Slide Lid fra Klean Kanteen er et skydelåg til 90 mm åbninger i farven Dawn Blue. Det passer til termokrus og take-away-kopper og kan betjenes med én hånd. Skub låget til side for at drikke, og luk igen for at undgå sprøjt.</p>' ],
	[ 'eans' => [ '0763332085359' ], 'html' => '<p>Dette Rise Slide-låg fra Klean Kanteen har lås, passer til 78 mm åbninger og er lyseblåt. Det er stænksikkert, har en rummelig åbning og lader varme drikke køle en smule hurtigere. Det er til morgenkaffe eller isvand på farten.</p>' ],
	[ 'eans' => [ '6411801005974' ], 'html' => '<p>Mainio-koppen fra Arabia i sarastus rummer 0,4 liter og er den store størrelse i serien. Den kan bruges til varme drikke, men også til smoothies eller suppe. Serien består af service.</p>' ],
	[ 'eans' => [ '7320061184338' ], 'html' => '<p>Sundborn-kruset fra Rörstrand rummer 30 cl og er i porcelæn. Formen er nationalromantisk, og mønstret er varmt og harmonisk. Serien er designet af Pia Rönndahl.</p>' ],
	[ 'eans' => [ '5606739961053' ], 'html' => '<p>Grespresso-lattekruset i hvid fra Costa Nova rummer 38 cl og er lavet i Portugal. Det er til en hjemmelavet latte, uanset om den er lavet på espresso, matcha eller noget tredje.</p>' ],
	[ 'eans' => [ '5606739961084' ], 'html' => '<p>Rosa lattekrus i Grespresso-serien fra Costa Nova rummer 38 cl. Det er lavet af robust stentøj og er beregnet til latte på espresso eller en cremet matcha.</p>' ],
	[ 'eans' => [ '5606739961060' ], 'html' => '<p>Det blå Grespresso-lattekrus fra Costa Nova er lavet i Portugal af stentøj med hård glasur. Det rummer 38 cl og passer til latte på espresso eller matcha.</p>' ],
	[ 'eans' => [ '5709846032682' ], 'html' => '<p>Emma-serien fra Stelton er tegnet af HolmbäckNordentoft og inspireret af dansk stentøjstradition. Sættet indeholder to grå krus på 15 cl med holdbar glasur og elegant, mat finish.</p>' ],
	[ 'eans' => [ '5606739979201' ], 'html' => '<p>Summer Blizz fra Costa Nova er et håndlavet krus i stentøj fra Portugal. Det rummer næsten en halv liter og passer til store kopper kaffe, te eller varm kakao. Farverne er sydlandske.</p>' ],
	[ 'eans' => [ '7320062103833' ], 'html' => '<p>Daga-koppen i okra fra Rörstrand rummer 33 cl og er af varmebestandigt stentøj. Designet er minimalistisk, og farven er hentet fra Kullabygdens ler.</p>' ],
	[ 'eans' => [ '5711507019635' ], 'html' => '<p>Rhombe Color-kruset i terracotta fra Lyngby Porcelæn rummer 33 cl. Det er håndlavet porcelæn og har rene linjer og simpelt mønster. Terracotta er en af seriens 7 farver.</p>' ],
	[ 'eans' => [ '5711841142327' ], 'html' => '<p>Lyngby Caféglas rummer 42 cl og sælges i en pakke med 4 stk. i æske. De er af hærdet maskinlavet glas, kan tåle opvaskemaskine og bruges til både varme og kolde drikke.</p>' ],
	[ 'eans' => [ '5709513353430' ], 'html' => '<p>Vandglassene fra Rosendahl Grand Cru rummer 22 cl og sælges 6 stk. i pakken. De er af hærdet glas og kan bruges til både koldt og varmt. Glassene har en diameter øverst på 7,5 cm.</p>' ],
	[ 'eans' => [ '5709513353454' ], 'html' => '<p>Caféglassene fra Rosendahl Grand Cru sælges i en pakke med 4 stk. og er af hærdet glas. De er 13,5 cm høje og 8 cm i diameter øverst og kan bruges til både varme og kolde drikke.</p>' ],
	[ 'eans' => [ '5709846031173' ], 'html' => '<p>To Go Click-termokoppen fra Stelton har Mumi-motiv i camping-udgaven. Den er dobbeltvægget, holder varmt i op til 2 timer og koldt i op til 4 timer og rummer 0,2 liter. Materialerne er rustfrit stål og BPA- og phthalatfri plast.</p>' ],
	[ 'eans' => [ '5709846031210' ], 'html' => '<p>Present-udgaven af Stelton To Go Click har Mumi-motiv og rummer 0,2 liter. Den er dobbeltvægget og holder varmt i op til 2 timer og koldt i op til 4 timer. Den er af rustfrit stål og BPA- og phthalatfri plast.</p>' ],
	[ 'eans' => [ '5709846034235' ], 'html' => '<p>Moomin Mamma\'s Tea Party er motivet på denne To Go Click-termokop fra Stelton. Koppen rummer 0,2 liter og er dobbeltvægget, med 2 timers varme og 4 timers kulde. Den er af rustfrit stål og BPA- og phthalatfri plast.</p>' ],
	[ 'eans' => [ '6411923686112' ], 'html' => '<p>Teema-kruset i kirsebærrød fra Iittala rummer 30 cl. Serien er designet af Kaj Franck og er kendt for et enkelt og funktionelt formsprog. Farven er dyb og rød.</p>' ],
	[ 'eans' => [ '5713524046502' ], 'html' => '<p>Ceto-koppen fra Muubs rummer 40 cl i farven mocha. Serien er inspireret af japansk keramiktradition og er af stentøj med håndværksmæssige detaljer, så hvert stykke er unikt.</p>' ],
	[ 'eans' => [ '7330033910636' ], 'html' => '<p>Primus-kruset rummer 30 cl og er af fødevaregodkendt 18/8 rustfrit stål. Det kan bruges på vandreturen, i båden, i sommerhuset og derhjemme.</p>' ],
	[ 'eans' => [ '6411255069041' ], 'html' => '<p>Iso Unikko-kruset fra Marimekko rummer 2,5 dl og er i hvidt stentøj med farverne karamel og orange. Det hører til Oiva-serien fra Sami Ruotsalainen og har det store Unikko-mønster.</p>' ],
	[ 'eans' => [ '5712195084516' ], 'html' => '<p>Mushroom-børnekruset fra OYOY Mini er i blå silikone. Det er blødt at holde om og robust nok til at tåle hverdagen. Kruset passer til børnenes små drikkepauser.</p>' ],
	[ 'eans' => [ '8004399335707' ], 'html' => '<p>Selezione fra De\'Longhi er kaffebønner i 250 g pakke. Blandingen er mellemristet og består af 70 % Arabica og 30 % Robusta. Kaffen har noter af frugt og blomster og en sød krop.</p>' ],
	[ 'eans' => [ '6410412838490' ], 'html' => '<p>Maku-glassene er to dobbeltvæggede kaffeglas på 25 cl. De kan bruges til både varme og kolde drikke, og isoleringen hjælper med at holde temperaturen. Du undgår også at brænde fingrene.</p>' ],
	[ 'eans' => [ '5710688197170' ], 'html' => '<p>Nordic Vanilla fra Broste Copenhagen er en kaffekop med underkop på 15 cl i stentøj. Den har en cremefarvet bund med et meleret mønster og et rustikt udtryk.</p>' ],
	[ 'eans' => [ '7320062103598' ], 'html' => '<p>Swedish Grace i dimma er et porcelænskrus på 30 cl fra Rörstrand. Det kan bruges til morgenkaffe og eftermiddagste. Louise Adelborg tegnede serien i 1930\'erne.</p>' ],
	[ 'eans' => [ '7026171050043' ], 'html' => '<p>Linen-kruset fra Magnor rummer 35 cl og er designet af den norske indretningsarkitekt Halvor Bakke. Det har en brun hørstruktur og et moderne design, inspireret af naturen.</p>' ],
	[ 'eans' => [ '7320062101389' ], 'html' => '<p>Eden-kruset fra Rörstrand rummer 34 cl og tåler op til 250 grader. Det er dekoreret med et delt æble med blade, et mønster tegnet i 1960 af maleren Sigrid Richter.</p>' ],
	[ 'eans' => [ '6411254994214' ], 'html' => '<p>Tiiliskivi betyder mursten, og mønsteret på dette grønne OIVA-krus fra Marimekko findes som relief. Armi Ratia, Marimekkos grundlægger, skabte det oprindelige mønster. Kruset rummer 2,5 dl.</p>' ],
	[ 'eans' => [ '6411254994122' ], 'html' => '<p>Karuselli-kruset fra Marimekko rummer 2,4 dl og er i Oiva-serien. Mønsteret er skabt med en reliefteknik, der giver overfladen struktur. Det kan bruges til varme drikke, men også til kolde drikke og smoothies.</p>' ],
	[ 'eans' => [ '6411254969687' ], 'html' => '<p>Kukat Puhkeavat fra Marimekko rummer 2,5 dl og er i hvidt stentøj. Det har et lille blomstermotiv på hanken, og udtrykket er skandinavisk og enkelt.</p>' ],
	[ 'eans' => [ '6411254880166' ], 'html' => '<p>Unikko betyder valmue på finsk og er Marimekkos symbol på kreativitet. Dette ISO Unikko-krus i hvid og rød rummer 2,5 dl. Mønsteret blev skabt af Maija Isola.</p>' ],
	[ 'eans' => [ '6411254832066' ], 'html' => '<p>OIVA Losange-kruset fra Marimekko rummer 2,5 dl og er dekoreret med kunst af den tyske kunstner Sabine Finkenauer. Kruset er af hvidt stentøj og tåler opvaskemaskine.</p>' ],
	[ 'eans' => [ '6411254832684' ], 'html' => '<p>OIVA Unikko-kruset i off white fra Marimekko rummer 2,5 dl og er af stentøj. Maija Isola designede Unikko-valmuemønsteret i 1960\'erne.</p>' ],
	[ 'eans' => [ '6411254770528' ], 'html' => '<p>Rusakko-mønsteret pryder dette OIVA-krus fra Marimekko i multifarver. Kruset er tegnet af Sami Ruotsalainen og rummer 2,5 dl.</p>' ],
	[ 'eans' => [ '5713959012684' ], 'html' => '<p>Colorit-kruset i gul fra Knabstrup rummer 0,25 liter. Colorit er den farverige søsterserie til Knabstrups klassiske service fra 1960\'erne, og designet er enkelt og stilrent.</p>' ],
	[ 'eans' => [ '5713959012639' ], 'html' => '<p>Colorit-kruset i coral fra Knabstrup rummer 0,25 liter. Det er farverig søster til Knabstrups klassiske service fra 1960\'erne. Formen er enkel.</p>' ],
	[ 'eans' => [ '5020403172314' ], 'html' => '<p>Det blå Tiki-krus fra Genware er af robust stentøj og rummer 40 cl, svarende til 14 oz. Det bruges til servering af cocktails med tropisk stemning.</p>' ],
	[ 'eans' => [ '5020403174752' ], 'html' => '<p>Astor Tiki-kruset fra Genware rummer 35 cl og er af stentøj med detaljeret design. Det er til tropiske drinks i baren eller ved bordet.</p>' ],
	[ 'eans' => [ '5020403172963' ], 'html' => '<p>Dette Tiki-krus fra Genware har en mørk, rå støbejernseffekt og rummer 40 cl. Det er til cocktails med teatralsk stemning.</p>' ],
	[ 'eans' => [ '5020403172222' ], 'html' => '<p>Det grønne Tiki-krus fra Genware er af robust stentøj og rummer 40 cl, svarende til 14 oz. Det er til cocktails med festlig stemning.</p>' ],
	[ 'eans' => [ '5020403172253' ], 'html' => '<p>Det brune Tiki-krus fra Genware rummer 40 cl. Brun finish giver et autentisk udtryk til klassiske tiki-drinks.</p>' ],
	[ 'eans' => [ '5020403172284' ], 'html' => '<p>Det lilla Tiki-krus fra Genware er af robust stentøj og rummer 40 cl. Der er plads til knust is og juice.</p>' ],
	[ 'eans' => [ '5020403176565' ], 'html' => '<p>Hammered Belly er en Tiki-kop fra Genware på 40 cl, svarende til 14 oz. Den hamrede overflade ses på det røde stentøj.</p>' ],
	[ 'eans' => [ '7320062023407' ], 'html' => '<p>Mon Amie-kruset fra Rörstrand er i porcelæn. Mønsteret er skabt af Marianne Westman, som skitserede en mosepost på en midsommeraften i 1940\'erne.</p>' ],
	[ 'eans' => [ '6411923690508' ], 'html' => '<p>Teema-espressokoppen i hvid fra Iittala rummer 10 cl. Kaj Franck formgav serien med nedtonet og funktionel æstetik. Koppen er lavet i porcelæn.</p>' ],
	[ 'eans' => [ '6411923690515' ], 'html' => '<p>Teema-espressokoppen i farven espresso fra Iittala rummer 10 cl. Den har en dyb, kaffeinspireret nuance og er lavet af porcelæn.</p>' ],
	[ 'eans' => [ '6411923690522' ], 'html' => '<p>Teema-espressokoppen i rav fra Iittala rummer 10 cl. Bærnstenstonen er varm, og designet er Kaj Francks klassiske. Koppen er af slidstærkt porcelæn.</p>' ],
	[ 'eans' => [ '5709846001800' ], 'html' => '<p>Vippeproppen er en reservedel til Stelton EM termokanden. Har kanden brug for nyt låg, kan du nøjes med at udskifte låget i stedet for hele kanden.</p>' ],
	[ 'eans' => [ '7340088505909' ], 'html' => '<p>Vagabond-kruset fra Stabilotherm er af rustfrit stål af typen SS304. Materialet afgiver hverken smag eller lugt. Kruset er enkelt og funktionelt.</p>' ],
	[ 'eans' => [ '6411800072533' ], 'html' => '<p>Teema-koppen fra Iittala rummer 22 cl og tåler maskinopvask, mikrobølgeovn og fryser. Serien har mange kombinationer af størrelser, former og farver.</p>' ],
	[ 'eans' => [ '7340115488588' ], 'html' => '<p>Trækoppen fra Hällmark rummer op til 15 cl og måler 15 x 6 cm. Den kan bruges som målebæger eller til at drikke af og tages med på udflugt eller vandretur.</p>' ],
	[ 'eans' => [ '5703779160627' ], 'html' => '<p>Hammershøi-kruset i antracit fra Kähler rummer 33 cl og er af porcelæn med de karakteristiske riller. Serien findes i flere farver, der kan kombineres.</p>' ],
	[ 'eans' => [ '5711173155668' ], 'html' => '<p>Sandrine-koppen i blåt stentøj fra Bloomingville har organisk form og en behagelig tyngde. Glasuren giver levende farvenuancer, så hver kop ser lidt forskellig ud.</p>' ],
	[ 'eans' => [ '5020403173328' ], 'html' => '<p>Bambus Tiki-kruset fra Genware rummer 50 cl og er af holdbart stentøj. Overfladen har en detaljeret bambusstruktur. Det er til cocktails med tropisk stemning.</p>' ],
	[ 'eans' => [ '4977642836914' ], 'html' => '<p>Yunomi-koppene fra Hario er varmebestandige og i klart glas. De rummer 17 cl og sælges to ad gangen. Det rene formsprog viser drikkens farve og er inspireret af japansk design.</p>' ],
	[ 'eans' => [ '5711173315109' ], 'html' => '<p>Reanna-kruset fra Bloomingville rummer 50 cl og er i grønt stentøj med en flettet detalje. Glasuren er dyb grøn, og kruset har et rustikt udtryk.</p>' ],
	[ 'eans' => [ '5020403176671' ], 'html' => '<p>Blue Fish Tiki-kruset fra Genware rummer 38 cl, svarende til 13,4 oz, og er formet som en dybblå fisk. Det er til Mai Tai og andre cocktails.</p>' ],
	[ 'eans' => [ '5020403176640' ], 'html' => '<p>Green Fish Tiki-kruset fra Genware rummer 38 cl, svarende til 13,4 oz. Det er formet som en stiliseret fisk i stentøj med blank, dybgrøn glasur.</p>' ],
	[ 'eans' => [ '7340194800042' ], 'html' => '<p>Vince-kruset fra Tell Me More er af hvidglaseret stentøj. Den reaktive glasur giver hvert krus et unikt udtryk.</p>' ],
	[ 'eans' => [ '5710688327102' ], 'html' => '<p>To Miko-krus fra Broste Copenhagen i farven warm grey, 15 cl hver. Formen mixer nordisk enkelhed med japansk inspiration. Krusene færdiggøres i hånden, så form, farve og glasur varierer en smule, og hvert sæt er unikt.</p>' ],
	[ 'eans' => [ '5710688327089' ], 'html' => '<p>Miko-kopperne i mørkegrøn fra Broste Copenhagen kombinerer japansk inspireret form og nordisk ro. De er færdiggjort i hånden, så der er små forskelle i form, glasur og farve.</p>' ],
	[ 'eans' => [ '5713524041835' ], 'html' => '<p>Ceto-kruset i mocha fra Muubs er stentøj i en dyb, fyldig mokkafarve. Serien er inspireret af japansk keramik, og den reaktive glasur giver hvert produkt sin egen form og farve.</p>' ],
	[ 'eans' => [ '7340194804262' ], 'html' => '<p>Taranto-kruset i størrelsen large er af glaseret stentøj i sandfarve. Hvert krus har sin egen karakter i form, farve og følelse, og det tåler opvaskemaskine.</p>' ],
	[ 'eans' => [ '7331423013531' ], 'html' => '<p>MyCup\'n Lid Original fra Light My Fire er et låg i musty yellow med åbning, hvor du kan drikke direkte eller bruge et genanvendeligt sugerør. Det tætsluttende låg gør, at kaffe, te eller kolde drikke kan tages med.</p>' ],
	[ 'eans' => [ '5709513208136' ], 'html' => '<p>Take-kopperne fra Rosendahl Grand Cru i grå er til udendørs brug, 30 cl og sælges to ad gangen. De er slidstærke, kan bruges igen og igen og passer til varme og kolde drikke.</p>' ],
	[ 'eans' => [ '3050910197175' ], 'html' => '<p>Eden-espressokoppen fra Pillivuyt rummer 8 cl. Størrelsen passer til espresso, og designet er enkelt og tidløst, til hverdag og særlige lejligheder.</p>' ],
	[ 'eans' => [ '5706631185646' ], 'html' => '<p>Nordic Kitchen-kruset fra Eva Solo rummer 40 cl og er i sort, matglaseret stentøj. Det har rustikt udtryk og tåler opvaskemaskine og mikrobølgeovn.</p>' ],
	[ 'eans' => [ '7332481078029' ], 'html' => '<p>Kaffekoppen fra Ernst er i porcelæn, 20 cl, og kommer med underkop. Farven er sandgrå med små prikker. Koppen er en del af en større serie med tekopper, kagetallerkener, kagefade og mælkekander.</p>' ],
	[ 'eans' => [ '7332481078012' ], 'html' => '<p>Tekoppen fra Ernst rummer 50 cl og er af porcelæn i sandgrå med små prikker. Den er en del af en større serie, hvor delene kan kombineres på kaffebordet.</p>' ],
	[ 'eans' => [ '5709513208600' ], 'html' => '<p>Take-krusene fra Rosendahl Grand Cru i svag grøn er to krus á 30 cl til picnic og ture i skoven. De er slidstærke og passer til både varme og kolde drikke.</p>' ],
	[ 'eans' => [ '5709513205036' ], 'html' => '<p>Cottage-kruset fra Rosendahl Grand Cru rummer 30 cl. Det hvide Grand Cru-design er forvandlet med en dekoration fra norske Fam Irvoll og giver nostalgi i de kolde måneder.</p>' ],
	[ 'eans' => [ '6411801018530' ], 'html' => '<p>Mainio-kruset i sand fra Arabia rummer 0,3 liter. Serien fås i mange farver, som kan matches og kombineres. Kruset passer til varme drikke.</p>' ],
	[ 'eans' => [ '7340115488571' ], 'html' => '<p>Trækoppen fra Hällmark er lavet af gummitræ og er beregnet til camping, telttur og vandreture. Den er kendt som kop til spejdere og lignende friluftsbrug.</p>' ],
	[ 'eans' => [ '7320061191169' ], 'html' => '<p>Swedish Grace i hvid, 30 cl, er et krus fra Rörstrand. Louise Adelborg tegnede serien i 1930, og mønstret er simpelt og klassisk.</p>' ],
	[ 'eans' => [ '5711173240616' ], 'html' => '<p>Bea-krusene fra Bloomingville sælges i sæt med 6 stk. De er af solidt stentøj med crackle-glasur og et blomstermotiv. Farven er natur.</p>' ],
	[ 'eans' => [ '5711173272457' ], 'html' => '<p>Senna-kruset fra Bloomingville er i slidstærkt stentøj med dyb, varm brun nuance og glaseret finish. Det passer til kaffe og te.</p>' ],
	[ 'eans' => [ '5020403223375' ], 'html' => '<p>Terra Porcelain Rose fra Genware er et krus på 30 cl, svarende til 10,5 oz. Farven er en støvet rosa, og den reaktive glasur giver et organisk udtryk.</p>' ],
	[ 'eans' => [ '7320062027719' ], 'html' => '<p>Underkoppen fra Swedish Grace passer til tekoppen på 45 cl i samme serie. Louise Adelborg designede serien, og underkoppen kan vaskes i opvaskemaskine og bruges i mikrobølgeovn.</p>' ],
	[ 'eans' => [ '5712195084479' ], 'html' => '<p>Mushroom-børnekruset fra OYOY Mini er rødt og lavet af 100 % silikone. Det er blødt at holde om og robust nok til at klare måltidet.</p>' ],
	[ 'eans' => [ '7340149800455' ], 'html' => '<p>BON-kruset fra Decotique i farven steam er af håndlavet stentøj. Små variationer i farve og tekstur giver hvert krus sit eget udseende.</p>' ],
	[ 'eans' => [ '5710688200184' ], 'html' => '<p>Nordic Sea-espressokoppen fra Broste Copenhagen kommer med underkop og er af stentøj med reaktiv glasur. Serien fås i to varianter.</p>' ],
	[ 'eans' => [ '4003686436138' ], 'html' => '<p>Afina-underkoppen til espressokop fra Villeroy & Boch har en diameter på 11,5 cm. Den matcher espressokoppen i serien.</p>' ],
	[ 'eans' => [ '5020403225652' ], 'html' => '<p>Terra Porcelain Rose-kaffekoppen fra Genware rummer 28,5 cl, svarende til 10 oz. Den bløde, støvede rosa nuance varierer fra kop til kop på grund af den reaktive glasur.</p>' ],
	[ 'eans' => [ '5020403224761' ], 'html' => '<p>Terra Porcelain i mat grå er en kaffekop på 28,5 cl fra Genware. Den reaktive glasur leder tankerne hen på hånddrejet keramik.</p>' ],
	[ 'eans' => [ '5020403225294' ], 'html' => '<p>Terra Aqua i blå er en kaffekop på 28,5 cl fra Genware. Glasuren er reaktiv og farvespillet gør hver kop forskellig.</p>' ],
	[ 'eans' => [ '5020403147510' ], 'html' => '<p>Terra Roko Sand-kaffekoppen fra Genware rummer 28,5 cl og er af slidstærkt porcelæn. Den har en dryppet glasureffekt.</p>' ],
	[ 'eans' => [ '5711173303465' ], 'html' => '<p>Emilo-koppen i grå stentøj fra Bloomingville rummer 30 cl. Den har et afdæmpet udtryk og passer til både moderne og traditionelle borddækninger.</p>' ],
	[ 'eans' => [ '5020403224938' ], 'html' => '<p>Terra Porcelain Grey er en kaffekop på 28,5 cl fra Genware. Den dybe grå nuance og reaktive glasur gør, at ikke to kopper er helt ens.</p>' ],
	[ 'eans' => [ '5020403083870' ], 'html' => '<p>Terra Porcelain Seafoam-kruset fra Genware rummer 30 cl, svarende til 10,5 oz. Glasuren skifter i afdæmpede grønblå nuancer.</p>' ],
	[ 'eans' => [ '5020403083955' ], 'html' => '<p>Seafoam-kaffekoppen fra Genware i serien Terra Porcelain rummer 28,5 cl. Den reaktive glasur giver havgrønne farvetoner.</p>' ],
	[ 'eans' => [ '5706631075350' ], 'html' => '<p>Legio Nova-koppen fra Eva Trio rummer 40 cl og har et minimalistisk design med riller. Den tåler ovn, mikroovn, fryser og opvaskemaskine og har 10 års porcelænsgaranti.</p>' ],
